import { i18n } from 'src/boot/i18n';
import type { dynamicObj } from 'src/pages/assets';
import { isObjectEmtpy } from 'src/utils/general';
import { useDocAttributesStore, useSettingStore } from 'src/store/main';
import { isDocTypeInvoice, CONSTANTS, doc_auto_match_and_export } from 'src/constants';
import { notify } from 'src/components/notifications/notify';
import { AUTO_EXPORT_PO_STATUSES } from 'src/pages/PurchaseOrders/constants.js';

export const AUTO_MATCH_AND_EXPORT_TOAST_ID =
  'auto-match-and-export-document-override';

export function isAutoMatchAndExportEnabledGlobally(): boolean {
  const { user_settings } = useSettingStore();
  return Boolean(user_settings?.[CONSTANTS.po_auto_match_and_export]);
}

// A document can only ever opt OUT of auto export, never into it, so a stale
// `true` left on a record cannot resurrect auto export once the user setting
// has been switched off.
export function isAutoMatchAndExportEnabled(record: dynamicObj): boolean {
  return (
    isAutoMatchAndExportEnabledGlobally() &&
    record?.[doc_auto_match_and_export] !== false
  );
}

// DOCB-8053: the one place that decides whether the PO page may export a
// document on its own right after a PO match. Used by the page-load check
// (`checkAutoExport`) and by the "Auto Match" button (`autoPoMatchAndExport`)
// so both paths apply exactly the same gates:
//   1. the match result is exportable (`full_matched` / `no_matchable_po_lines`),
//   2. no amount is still pending,
//   3. "PO Auto Match and Export" is on for the org and not opted out on the doc.
export function shouldAutoExportAfterPoMatch(
  record: dynamicObj | null | undefined,
  pendingAmount: string | number | null | undefined,
): boolean {
  const status = record?.po_match_status;
  if (!status || !AUTO_EXPORT_PO_STATUSES.includes(status)) {
    return false;
  }

  if (pendingAmount !== undefined && pendingAmount !== null && `${pendingAmount}` !== '') {
    const pending = parseFloat(`${pendingAmount}`.replace(/[^0-9]/g, ''));
    if (pending > 0) {
      return false;
    }
  }

  return isAutoMatchAndExportEnabled(record as dynamicObj);
}

export interface AutoMatchThenExportPage {
  /** Runs the PO auto match; resolves true only when the match succeeded. */
  autoPoMatch: () => Promise<boolean>;
  /** The (possibly replaced) document record after the match. */
  getRecord: () => dynamicObj | null | undefined;
  getPendingAmount: () => string | number | null | undefined;
  /** The export buttons component (`$refs.exportBtns`), if rendered. */
  getExportBtns: () => { confirmAndExport?: (auto?: boolean) => unknown } | null | undefined;
}

// DOCB-8053: what the "Auto Match" button does. Match first; then, when the
// result passes the shared export gates, export right away — the same thing
// the page-load check does when the document was opened via "PO Match" from
// the validation screen. Resolves true only when an export was triggered.
export async function autoMatchThenExport(page: AutoMatchThenExportPage): Promise<boolean> {
  const matched = await page.autoPoMatch();
  if (!matched) {
    return false;
  }
  if (!shouldAutoExportAfterPoMatch(page.getRecord(), page.getPendingAmount())) {
    return false;
  }
  const exportBtns = page.getExportBtns();
  if (!exportBtns || typeof exportBtns.confirmAndExport !== 'function') {
    return false;
  }
  // DRFS-741: true marks this as the automatic Auto-Match-and-Export action,
  // so the API can enforce the module switch itself.
  exportBtns.confirmAndExport(true);
  return true;
}

export function setAutoMatchAndExportForDocument(
  record: dynamicObj,
  enabled: boolean,
) {
  if (enabled) {
    delete record[doc_auto_match_and_export];
  } else {
    record[doc_auto_match_and_export] = false;
  }

  notify.warning(
    i18n.t(
      enabled
        ? 'auto_export_enabled_for_document'
        : 'auto_export_disabled_for_document',
    ),
    { id: AUTO_MATCH_AND_EXPORT_TOAST_ID },
  );
}

export default {
  methods: {
    poActionDisableStatusList() {
      return ['error', 'running', 'restart_in_progress'];
    },

    async isPoSettingActivate(doc_type: string) {
      const doc_attribute_store = useDocAttributesStore();
      await doc_attribute_store.fetchAttributes(doc_type);
      const { model } = doc_attribute_store;

      const po_activate = model[CONSTANTS.is_po_active];
      if (po_activate === undefined || po_activate == '') {
        return false;
      }
      return po_activate === 'true' || po_activate === true ? true : false;
    },

    async getPOUrl (doc_type:string) {

      const doc_attribute_store = useDocAttributesStore();
      await doc_attribute_store.getDocTypeAllSettings();

      const isServerSideMatching = doc_attribute_store.getSettingsByDocTypeAndSettingKey(doc_type, CONSTANTS.PO_MATCH_SERVER_SIDE)

      return isServerSideMatching ? '/po-matching/' : '/po-matching-v3/';
    },

    isPoIconAllowed (status: string, table_version : any, invoice_sub_type = null) {
      if (invoice_sub_type == 'Cost Invoice') {
        return false;
      }

      if (table_version === null) {
        return false;
      }
      if (this.poActionDisableStatusList().includes(status)) {
        return false;
      }

      return true;
    },
    getMandatoryColumnsForPo(doc_type: string) {
      const mandatoryColums = ['quantity', 'item_number', 'net_amount'];
      if (doc_type != 'DELIVERY_NOTE') {
        mandatoryColums.push('unit_price');
      }
      return mandatoryColums;
    },
    hasLineItems(tables: any): boolean {
      return !(
        !tables ||
        tables.length == 0 ||
        isObjectEmtpy(tables) ||
        !tables[0] ||
        !tables[0].rows ||
        !tables[0].rows[0]
      );
    },
    getMissingMandatoryColumns(tables: any, doc_type: string): string[] {
      // validate table columns if it contains Item Number, Unit Price, Quantity, Net amount
      const mandatoryColums = this.getMandatoryColumnsForPo(doc_type);

      if (mandatoryColums.length == 0) {
        return mandatoryColums;
      }

      const tableRows = tables[0].rows[0];
      Array.from(tableRows.columns).forEach((column: any) => {
        const index = mandatoryColums.indexOf(column.name.toLowerCase());
        if (index > -1) {
          mandatoryColums.splice(index, 1);
        }
      });

      return mandatoryColums;
    },
    validateLineItemTable(tables: any, doc_type: string): boolean {
      if (!this.hasLineItems(tables)) {
        notify.warning(
          i18n.t('po_restrict_message_not_items'),
        );
        return false;
      }

      if (this.getMissingMandatoryColumns(tables, doc_type).length > 0) {
        notify.warning(
          i18n.t('MISSING_MANDATORY_COLUMNS'),
        );
        return false;
      }

      return true;
    },
    cleanItemNumber(itemNumber: string) {
      if(!itemNumber) { return ''; }
      const characters_to_remove = [' ', '`', '*', '_','{', '}', '[', ']','(', ')', '>', '#','+', '-', '.', ',','!', '$', '\''];
      for(const char of characters_to_remove) {
        itemNumber = itemNumber.split(char).join('');
      }

      return itemNumber;
    },
  },
};
