/**
 * The single definition of the "show / hide non mapped columns" rule.
 *
 * DOCB-14440. A table column reaches the grid two ways, and only one of them
 * sets `is_mapped`:
 *
 *   - mapped        — a column of the recognised table was assigned to a
 *                     DocBits column, so the cell carries `is_mapped` and
 *                     `org_index`;
 *   - hand-trained  — a trained extraction rule fills the column per row, so
 *                     the cell carries `rule` and `extraction_method` and
 *                     neither `is_mapped` nor `org_index`.
 *
 * The backend's export filter already keeps both
 * (`helpers/doc_table_helper.py remove_unmapped_columns_for_export`), so every
 * table view has to keep both as well, or a column survives export and
 * disappears from the grid.
 *
 * This lives outside the document store on purpose: the store action delegates
 * to it, and so can a test that mocks the store, instead of restating the rule
 * in a stub that would stay green while production regressed.
 */
export function isNonMappedColumnAllowed(
  column: any,
  hideUnmapped: boolean,
): boolean {
  const is_mapped = column && column.is_mapped ? column.is_mapped : false;
  // A hand-trained column carries a rule instead of is_mapped/org_index.
  const has_rule = column && column.rule ? true : false;
  return Boolean(is_mapped) || has_rule || !hideUnmapped;
}
