/**
 * Grafana Faro - Real User Monitoring (RUM)
 *
 * Captures Core Web Vitals, page performance, errors, and user sessions
 * for comprehensive frontend observability.
 *
 * CORE-6333: this boot file only decides whether Faro should run. The SDK,
 * its configuration (instrumentations, propagateTraceHeaderCorsUrls for the
 * `traceparent` header, ignoreErrors, beforeSend) and the collector health
 * check live in src/utils/telemetry/faro-sdk.ts, loaded with import() after
 * the first render so Faro and OpenTelemetry stay off the render path.
 * The helpers below (getFaro, setFaroUser, pushFaro*) work before and after
 * that: pushFaro* calls (and router errors) made before window.__faro exists
 * are queued, up to MAX_QUEUED_FARO_ITEMS, and flushed by faro-sdk.ts.
 *
 * Architecture (v2 - March 2026):
 * - Uses built-in FetchTransport (handles batching, payload format, retries)
 * - Preflight health check before initialization — skips Faro entirely if collector is down
 * - ConsoleInstrumentation with DEBUG/TRACE disabled to prevent feedback loops
 * - TracingInstrumentation ignores Faro collector URLs to prevent trace recursion
 * - Localhost detection disables Faro for local dev regardless of APP_VUE_STAGE
 *
 * Environment Variables:
 * - APP_VUE_STAGE: Environment name (dev, stage, sandbox, demo, prod, local)
 * - APP_VUE_BRANCH: Git branch (used for environment prefix)
 *
 * Created: January 2026
 * Rewritten: March 2026 — fixed request flood, removed custom transport
 */

import { boot } from 'quasar/wrappers';
import { buildFaroCollectorUrl } from 'src/pages/api-base-url';
import type { Faro } from '@grafana/faro-web-sdk';
import { safeBoot } from 'src/utils/bootSafety';
import { runAfterFirstRender } from 'src/utils/telemetry/deferTelemetry';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { getUserDetailFromkey } from 'src/utils/UserDetails';

import { runtimeEnv } from 'src/config/runtime-env';

/**
 * Boot function for Quasar
 */
export default boot(
  safeBoot('faro', ({ app, router }) => {
    const appEnv = runtimeEnv('APP_VUE_STAGE');
    const appVersion = process.env.APP_VERSION || '1.0.0';

    const isLocalhost =
      typeof window !== 'undefined' &&
      (window.location.hostname === 'localhost' ||
        window.location.hostname === '127.0.0.1');
    if (appEnv === 'local' || isLocalhost) {
      console.info('[Faro] Disabled for local development');
      return;
    }

    const collectorUrl = buildFaroCollectorUrl();
    if (!collectorUrl) {
      return;
    }

    // vue-router swallows a failed first navigation; report it once Faro is up.
    const stopRouterErrors = router?.onError((error) =>
      pushFaroError(error instanceof Error ? error : new Error(String(error)), {
        source: 'router',
        phase: 'before-faro-init',
      }),
    );

    runAfterFirstRender(() => {
      import('src/utils/telemetry/faro-sdk')
        .then(({ initFaro }) =>
          initFaro({ app, router, collectorUrl, appEnv, appVersion }),
        )
        .catch((error) => {
          console.warn(
            '[Faro] Failed to load (app continues without telemetry):',
            error,
          );
        })
        .finally(() => stopRouterErrors?.());
    });
  }),
);

/**
 * Get the Faro instance for direct usage
 */
export function getFaro(): Faro | null {
  return (window as any).__faro || null;
}

const MAX_QUEUED_FARO_ITEMS = 50;
let faroQueue: Array<(faro: Faro) => void> = [];

function sendToFaro(send: (faro: Faro) => void): void {
  const faro = getFaro();
  if (faro) {
    send(faro);
  } else if (faroQueue.length < MAX_QUEUED_FARO_ITEMS) {
    faroQueue.push(send);
  }
}

/**
 * Send what pushFaro* queued before Faro was initialised (faro-sdk.ts).
 */
export function flushFaroQueue(faro: Faro): void {
  const queued = faroQueue;
  faroQueue = [];
  for (const send of queued) {
    try {
      send(faro);
    } catch {
      // Never let telemetry errors affect the app
    }
  }
}

/**
 * Set user context after login
 */
export function setFaroUser(user: {
  id: string | number;
  email?: string;
  organizationId?: string;
  subOrgId?: string;
  role?: string;
}): void {
  try {
    const faro = getFaro();
    if (faro) {
      faro.api.setUser({
        id: String(user.id),
        email: user.email,
        attributes: {
          organization_id: user.organizationId || '',
          sub_org_id: user.subOrgId || '',
          role: user.role || '',
        },
      });
    }
  } catch {
    // Never let telemetry errors affect authentication
  }
}

/**
 * Attach org/user context from an already-established session (storage) to
 * Faro, so every RUM item carries `organization_id` in its user meta.
 * Safe to call when logged out (no-op) or before Faro init (no-op).
 *
 * This is what makes server-side org scoping of RUM data possible
 * (DOCB-12254) — without it, Analytics queries cannot be filtered per org.
 */
export function syncFaroUserFromSession(): void {
  try {
    const orgId = getOrgId();
    const userId = getUserDetailFromkey('id');

    if (!orgId && !userId) {
      return; // not logged in — nothing to attach
    }

    setFaroUser({
      id: userId ? String(userId) : '',
      organizationId: orgId ? String(orgId) : '',
    });
  } catch {
    // Never let telemetry errors affect app startup
  }
}

/**
 * Clear user context on logout
 */
export function clearFaroUser(): void {
  try {
    const faro = getFaro();
    if (faro) {
      faro.api.resetUser();
    }
  } catch {
    // Never let telemetry errors affect logout
  }
}

/**
 * Push a custom event for business metrics
 */
export function pushFaroEvent(
  name: string,
  attributes?: Record<string, string>,
): void {
  try {
    const timestampOverwriteMs = Date.now();
    sendToFaro((faro) =>
      faro.api.pushEvent(name, attributes, undefined, { timestampOverwriteMs }),
    );
  } catch {
    // Never let telemetry errors affect application logic
  }
}

/**
 * Push an error to Faro
 */
export function pushFaroError(
  error: Error,
  context?: Record<string, string>,
): void {
  try {
    const timestampOverwriteMs = Date.now();
    sendToFaro((faro) =>
      faro.api.pushError(error, { context, timestampOverwriteMs }),
    );
  } catch {
    // Never let telemetry errors affect error handling
  }
}

/**
 * Add a measurement (timing, count, etc.)
 */
export function pushFaroMeasurement(
  type: string,
  values: Record<string, number>,
  context?: Record<string, string>,
): void {
  try {
    const timestampOverwriteMs = Date.now();
    sendToFaro((faro) =>
      faro.api.pushMeasurement(
        { type, values, context },
        { timestampOverwriteMs },
      ),
    );
  } catch {
    // Never let telemetry errors affect performance tracking
  }
}
