/**
 * DOP-70: the trace id of a failed request, so every error the user sees can
 * show it.
 *
 * A customer reports an error with a screenshot of the toast and nothing else.
 * doc2-api and the auth service answer every request with an
 * `X-DocBits-Trace-Id` header and put the same id into the body of every
 * failure (`docbits_trace_id`); the web app sends that id itself on every
 * request (`src/utils/searchTrace.ts`), so even a request that never reached
 * the server has one. Shown under the message, it is the one thing in the
 * screenshot we can look up in the logs.
 *
 * Two ways in:
 * - `traceIdFromError(error)` reads it off an axios error, response or body;
 *   `ApiExceptions.getErrorMessage` attaches it to the message it builds.
 * - Most components pass `notify.error` only a translated string and never
 *   hand the error over. For those, the axios clients record the id of
 *   every failed request (`registerFailedTraceCapture`), and the toast falls
 *   back to the most recent one (`recentFailedTraceId`).
 */
import type { AxiosInstance } from 'axios';

export const TRACE_BODY_FIELD = 'docbits_trace_id';
const TRACE_HEADER = 'x-docbits-trace-id';

/** How long a failed request's id may be shown by a toast that has none. */
export const RECENT_FAILURE_WINDOW_MS = 10_000;

type Bag = Record<string, unknown>;

function isObject(value: unknown): value is Bag {
  return !!value && typeof value === 'object';
}

function nonEmpty(value: unknown): string {
  return typeof value === 'string' && value.trim() ? value.trim() : '';
}

function fromHeaders(headers: unknown): string {
  if (!isObject(headers)) return '';
  const get = (headers as { get?: (name: string) => unknown }).get;
  const viaGet =
    typeof get === 'function' ? get.call(headers, TRACE_HEADER) : undefined;
  return (
    nonEmpty(viaGet) ||
    nonEmpty(headers[TRACE_HEADER]) ||
    nonEmpty(headers['X-DocBits-Trace-Id'])
  );
}

function fromBody(body: unknown): string {
  let payload = body;
  while (Array.isArray(payload) && payload.length > 0) payload = payload[0];
  if (!isObject(payload)) return '';
  return (
    nonEmpty(payload[TRACE_BODY_FIELD]) ||
    (isObject(payload.data) ? nonEmpty(payload.data[TRACE_BODY_FIELD]) : '')
  );
}

/**
 * The trace id carried by anything an API call can throw or return: an axios
 * error, an axios response, a response body, or an object that already has a
 * `traceId`. Server id first (body, then header); the id the web app sent is
 * the fallback, so a request that failed before an answer still has one.
 */
export function traceIdFromError(error: unknown): string {
  if (!isObject(error)) return '';
  const own = nonEmpty(error.traceId);
  if (own) return own;

  const response = isObject(error.response) ? error.response : undefined;
  if (response) {
    const id = fromBody(response.data) || fromHeaders(response.headers);
    if (id) return id;
  }
  const direct =
    fromBody(error.data) || fromHeaders(error.headers) || fromBody(error);
  if (direct) return direct;

  const config = isObject(error.config) ? error.config : undefined;
  if (config) {
    return nonEmpty(config.__docbitsTraceId) || fromHeaders(config.headers);
  }
  return '';
}

let lastFailure: { id: string; at: number } | null = null;

export function rememberFailedTraceId(
  id: string,
  now: number = Date.now(),
): void {
  const traceId = nonEmpty(id);
  if (traceId) lastFailure = { id: traceId, at: now };
}

/** The id of the most recent failed request, if it failed within the window. */
export function recentFailedTraceId(now: number = Date.now()): string {
  if (!lastFailure) return '';
  return now - lastFailure.at <= RECENT_FAILURE_WINDOW_MS ? lastFailure.id : '';
}

export function clearFailedTraceId(): void {
  lastFailure = null;
}

function isSoftFailure(response: unknown): boolean {
  return (
    isObject(response) &&
    isObject(response.data) &&
    response.data.success === false
  );
}

/**
 * Record the trace id of every failed request made through `instance`:
 * rejected requests (4xx/5xx, network, timeout) and `200 {success: false}`
 * refusals. Never changes the response or the error.
 */
export function registerFailedTraceCapture(
  instance: Pick<AxiosInstance, 'interceptors'>,
): void {
  instance.interceptors.response.use(
    (response) => {
      if (isSoftFailure(response))
        rememberFailedTraceId(traceIdFromError(response));
      return response;
    },
    (error) => {
      // A 401 is refreshed and retried silently; it is not an error anyone sees.
      if (error?.response?.status !== 401)
        rememberFailedTraceId(traceIdFromError(error));
      return Promise.reject(error);
    },
  );
}
