/**
 * Table-extraction explanation client (DOCB-14569).
 *
 * One read: `GET /api/automation-intelligence/v1/documents/{doc_id}/
 * table-extraction-explanation`. It is what the AI table's "Show" button
 * renders when nothing has been changed yet — the configuration the document
 * met, the run that produced the table, where every column's value came
 * from, and what would make the next run better. Every sentence arrives in
 * DE and EN together; nothing here composes text.
 *
 * Extends `TouchlessService` for the same reason `PipelineExplanationService`
 * does: the auth/organisation plumbing of the analytics API lives there once.
 */

import TouchlessService from 'src/services/analytics/TouchlessService';
import { DOC2API_URL } from 'src/pages/APIs';
import type { PipelineText } from 'src/services/analytics/PipelineExplanationService';

export interface TableExplanationColumn {
  key: string;
  label: string;
  type: string;
  use_ai: boolean | null;
  required: boolean;
  hidden: boolean;
  requested_from_ai: boolean;
  hint: string | null;
  origin: string | null;
  raw_key: string | null;
  raw_name: string | null;
  raw_key_status: string | null;
  collision: boolean;
  example: string | null;
  basis: string | null;
  mapping_source: string | null;
  hidden_by: string | null;
  discarded_reason: string | null;
  filled_rows: number;
  row_count: number;
  state: 'filled' | 'partial' | 'empty' | string;
  how: PipelineText;
}

export interface TableExplanationCall {
  started_at: string | null;
  run_id: string | null;
  requested_model: string | null;
  served_model: string | null;
  /** Fast / Full / Nexus as the API resolved it for this call. */
  tier: string | null;
  provider: string | null;
  mode: string | null;
  structure_valid: boolean | null;
  category: string | null;
  transport_complete: boolean | null;
  cache_hit: boolean | null;
  pages: number[] | null;
  batch: string | null;
}

export interface TableExplanationRun {
  started_at: string | null;
  run_id: string | null;
  provider: string | null;
  requested_model: string | null;
  served_model: string | null;
  /** Fast / Full / Nexus — the only name the reader ever sees for the model. */
  tier: string | null;
  structured_output_used: boolean | null;
  structured_output_label: PipelineText;
  batch_count: number;
  mode: string | null;
  mode_label: PipelineText;
  strict_requested: boolean | null;
  structure_valid: boolean | null;
  category: string | null;
  category_label: PipelineText;
  transport_complete: boolean | null;
  cache_hit: boolean | null;
  provenance: Record<string, unknown>;
  requested_columns: string[];
  column_policy_state: string | null;
  column_policy_reason: string | null;
  calls: TableExplanationCall[];
}

export interface TableExplanationRecommendation {
  code: string;
  severity: 'high' | 'medium' | 'low' | string;
  title: PipelineText;
  text: PipelineText;
  setting?: string;
  route?: string;
  columns?: string[];
}

export interface TableExplanationStage {
  no: number;
  key: string;
  label: PipelineText;
  state: string;
  state_label: PipelineText;
  state_provenance: string;
  is_first_blocker: boolean;
  evidence_missing_reason: string | null;
  summary: PipelineText;
  duration_ms: number | null;
}

/** Structured output at a glance: one badge, two numbers, one explainer. */
export interface TableExplanationStructuredOutput {
  used: boolean | null;
  schema_valid: boolean | null;
  requested: number;
  filled: number;
  tone: 'ok' | 'warn' | 'unverified' | 'off' | 'unknown' | string;
  badge: PipelineText;
  label: PipelineText;
  explainer: PipelineText;
}

/** Who chose the tier: this supplier's layout, the organisation, or nobody. */
export interface TableExplanationModelSelection {
  source: 'supplier' | 'organization' | 'default' | 'unknown' | string;
  tier: string | null;
  value: string | null;
  label: PipelineText;
}

/** The four steps of the picture, as counts. */
export interface TableExplanationSteps {
  document: {
    filename: string | null;
    pages: number | null;
    doc_type: string | null;
  };
  extraction: {
    raw_columns: number;
    rows: number;
    mode: string;
    model: string | null;
    tier: string | null;
    tier_source: string;
    tier_source_label: PipelineText;
    structured_output_used: boolean | null;
    structured_output_label: PipelineText;
    structured_output: TableExplanationStructuredOutput;
  };
  mapping: {
    mapped: number;
    identity: number;
    discarded: number;
    collisions: number;
    unknown_raw: number;
  };
  result: {
    ai_columns: number;
    ai_columns_filled: number;
    non_ai_columns: number;
    hidden_columns: number;
    total_columns: number;
    rows: number;
  };
}

/** One improvement the KI-Advisor (Nexus) suggests; codes for the UI, labels for the reader. */
export interface TableExplanationImprovement {
  action: string;
  action_label: PipelineText;
  target: string | null;
  target_label: PipelineText | null;
  why: PipelineText;
  how: PipelineText;
  /** ADD_INSTRUCTION_TAG: a sentence ready for the prompt field (CORE-6192). */
  prompt_line?: PipelineText | null;
}

export interface TableExplanationAdvice {
  source: 'advisor';
  tier: 'Nexus' | string;
  summary: PipelineText;
  improvements: TableExplanationImprovement[];
}

export interface TableExplanationAdvisor {
  enabled: boolean;
  disabled_reason: string | null;
  requested: boolean;
  applied: boolean;
}

export interface TableExplanation {
  schema_version: string;
  doc_id: string;
  org_id: string;
  doc_type: string | null;
  filename: string | null;
  table_name: string | null;
  configuration: {
    mode: 'ai' | 'nonai' | string;
    ai_table_enabled: boolean | null;
    structured_output: {
      key: string;
      enabled: boolean | null;
      status: string;
      source: string;
    };
    model_preference: string | null;
    model_selection: TableExplanationModelSelection;
    layout: {
      tfidf_id: string | null;
      has_training_rule: boolean;
      rule_id: string | null;
      has_prompt: boolean;
      hint_count: number;
      hidden_columns: string[];
    };
    table_name: string;
    column_count: number;
    ai_column_count: number;
  };
  columns: TableExplanationColumn[];
  steps: TableExplanationSteps;
  run: TableExplanationRun | null;
  run_missing_reason: string | null;
  result: {
    row_count: number;
    columns_filled: string[];
    columns_empty: string[];
  };
  recommendations: TableExplanationRecommendation[];
  notes: {
    stops_at: PipelineText;
    not_shown: PipelineText;
    next_step: PipelineText;
  };
  narrative: PipelineText;
  stages: TableExplanationStage[];
  /** Only with `includeRecommendation`; null when the advisor is off or failed. */
  advice?: TableExplanationAdvice | null;
  advisor?: TableExplanationAdvisor;
}

export interface TableExplanationOptions {
  /** Ask the KI-Advisor (Nexus) too — slower (8–15 s), so callers do it in a second request. */
  includeRecommendation?: boolean;
  lang?: string;
}

export default class TableExplanationService extends TouchlessService {
  private explanationBase(): string {
    return `${DOC2API_URL}/api/automation-intelligence/v1`;
  }

  /** How the AI table of ONE document arrived at its values. */
  public async getDocumentTableExplanation(
    docId: string,
    tableName?: string | null,
    options: TableExplanationOptions = {},
  ): Promise<TableExplanation> {
    const params = new URLSearchParams();
    if (tableName) params.set('table_name', tableName);
    if (options.includeRecommendation)
      params.set('include_recommendation', 'true');
    if (options.lang) params.set('lang', options.lang);
    const query = params.toString() ? `?${params.toString()}` : '';
    const endpoint =
      `${this.explanationBase()}/documents/${encodeURIComponent(docId)}` +
      `/table-extraction-explanation${query}`;
    return await this.getWithoutOrgId(endpoint);
  }
}
