  createFormData(
    endpoint_information: any,
    record_type = '',
    mode = '',
  ): FormData {
    const formData = new FormData();
    if (mode == 'create') {
      formData.append('record_type', record_type);
    } else if (mode == 'edit') {
      formData.append('id', endpoint_information.id);
    }
    if (endpoint_information.sub_org_id) {
      formData.append('sub_org_id', endpoint_information.sub_org_id);
    }
    if (endpoint_information.auth_type.value === 'ionapi') {
      formData.append(
        'url',
        endpoint_information.dynamic_api
          ? endpoint_information.url_user_input_formatted
          : endpoint_information.url_user_input,
      );
    } else {
      formData.append('url', endpoint_information.url);
    }
    formData.append('method', endpoint_information.method.value);
    formData.append('body_type', endpoint_information.body_type.value);
    formData.append(
      'authentication_type',
      endpoint_information.auth_type.value,
    );
    formData.append('is_dynamic', endpoint_information.dynamic_api);
    const columns: any = {};
    endpoint_information.columns.forEach((column: any) => {
      columns[column.key] = column.value;
    });
    const params: any = {};
    if (endpoint_information.params) {
      endpoint_information.params.forEach((param: any) => {
        params[param.key] = param.value;
      });
    }
    let bodys: any = {};
    if (endpoint_information.body_type.value == 'multipart/form-data') {
      if (endpoint_information.body) {
        endpoint_information.body.forEach((body: any) => {
          bodys[body.key] = body.value;
        });
      }
    } else {
      if (endpoint_information.body_string) {
        bodys = JSON.parse(endpoint_information.body_string);
      }
    }
    const headers: any = {};
    if (endpoint_information.headers) {
      endpoint_information.headers.forEach((header: any) => {
        headers[header.key] = header.value;
      });
    }

    if (Object.keys(columns).length !== 0) {
      formData.append('column_paths', JSON.stringify(columns));
    }
    if (Object.keys(params).length !== 0) {
      formData.append('params', JSON.stringify(params));
    }
    if (Object.keys(bodys).length !== 0) {
      formData.append('body', JSON.stringify(bodys));
    }
    if (Object.keys(headers).length !== 0) {
      formData.append('headers', JSON.stringify(headers));
    }
    if (endpoint_information.auth_type != 'none') {
      formData.append('authentication_json', endpoint_information.auth_json);
    }
    return formData;
  }

