  public async createMasterData(
    endpoint_information: any,
    record_type: string,
    mode: string,
  ): Promise<any> {
    const formData = this.createFormData(
      endpoint_information,
      record_type,
      mode,
    );
    formData.append('data_base_path', endpoint_information.json_path_edited);
    formData.append('data_type', endpoint_information.data_type);
    if (endpoint_information.dynamic_api) {
      formData.set('url', endpoint_information.url_user_input);
      // SAL-35: saved with the config, so the backend can import the first
      // rows with them and the user does not have to find them again.
      formData.append(
        'sample_values',
        JSON.stringify(endpoint_information.sample_values || {}),
      );
    }
    if (mode === 'create') {
      return super.post(api.create_endpoint, formData);
    } else if (mode == 'edit') {
      return super.post(api.update_endpoint, formData);
    }
  }

