  public async getData_V2(
    data: dynamicObj,
    filter_data_json: string,
    form_data = {},
  ): Promise<any> {
    if (!data.hasOwnProperty('sub_org_id')) {
      const sub_org_id = await this.getSubOrgId();
      if (sub_org_id && sub_org_id !== this.getOrgId()) {
        data['sub_org_id'] = sub_org_id;
      }
    }
    const querystring = this.encodeQueryData(data);

    const formData = new FormData();
    for (const [key, value] of Object.entries(form_data)) {
      formData.append(key, String(value));
    }

    formData.append('filter_data_json', filter_data_json);
    return super.post(
      api.get_master_data_lookup_data_v2 + '?' + querystring,
      formData,
    );
  }

  // DOCB-14536: Auto Accounting searches large lookup lists on the server
  // instead of downloading them. `search_fields` are the properties the typed
  // text is matched against; `filters` are exact property matches every
  // record must satisfy (e.g. the dimension a value belongs to).
  public async searchMasterData(params: {
    data_type: string;
    q: string;
    search_fields: string[];
    filters?: Record<string, string>;
    limit?: number;
  }): Promise<{ data: dynamicObj[]; limit: number; truncated: boolean }> {
    const query: dynamicObj = {
      data_type: params.data_type,
      q: params.q ?? '',
      search_fields: params.search_fields.join(','),
      limit: params.limit ?? 50,
    };
    if (params.filters && Object.keys(params.filters).length > 0) {
      query.filters_json = JSON.stringify(params.filters);
    }
    const sub_org_id = await this.getSubOrgId();
    if (sub_org_id) {
      query.sub_org_id = sub_org_id;
    }
    return super.post(
      api.post_master_data_lookup_search + '?' + this.encodeQueryData(query),
      new FormData(),
    );
  }

  // One round trip for every saved account / prediction of a document: the
  // records whose `field` equals one of `values` (exact, case-insensitive).
  public async resolveMasterData(params: {
    data_type: string;
    field: string;
    values: string[];
  }): Promise<{ data: dynamicObj[] }> {
    const query: dynamicObj = {
      data_type: params.data_type,
      field: params.field,
    };
    const sub_org_id = await this.getSubOrgId();
    if (sub_org_id) {
      query.sub_org_id = sub_org_id;
    }
    const formData = new FormData();
    formData.append('values_json', JSON.stringify(params.values));
    return super.post(
      api.post_master_data_lookup_resolve + '?' + this.encodeQueryData(query),
      formData,
    );
  }

