  public async uploadCSV(formData: FormData) {
    const chunkSize = 500;
    this.uploadState.uploadProgress = '';
    this.uploadState.uploadedRecords = 0;
    this.uploadState.totalRecords = 0;

    const file = formData.get('file') as File;
    formData.delete('file');

    const csvData = await this.readFileAsText(file);
    const lines = this.getlines(csvData);
    this.uploadState.uploadProgress = `Preparing ${lines.length} record(s)`;
    this.uploadState.totalRecords = lines.length;

    const chunks = this.chunkCSVData(lines, chunkSize);

    for (let i = 0; i < chunks.length; i++) {
      const chunk = chunks[i];
      const data = this.copyFormData(formData);
      const rowsInChunk = chunk.length;

      if (i > 0) {
        chunk.unshift(lines[0]);
        data.delete('replace_all');
        data.append('replace_all', 'false');
      }

      const chunkCSV = this.convertToCSV(chunk);
      data.append('csv_data', chunkCSV);

      const success = await this.uploadChunk(data, rowsInChunk);
      if (!success) break;
    }
  }

  private readFileAsText(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = () => reject(reader.error);
      reader.readAsText(file);
    });
  }

  public copyFormData(formData: FormData): FormData {
    const newFormData = new FormData();

    formData.forEach((value, key) => {
      if (key != 'csv_data') {
        newFormData.append(key, value);
      }
    });

    return newFormData;
  }
  public getlines(csvData: string): string[] {
    if (typeof csvData !== 'string') {
      throw new Error('Input CSV data must be a string.');
    }
    // Split the input CSV string into rows based on new lines
    return csvData.split('\n');
  }

  public convertToCSV(data: string[]): string {
    if (!Array.isArray(data)) {
      throw new Error('Input data must be an array.');
    }

    // Simply join the rows with a newline
    return data.join('\n');
  }
  public chunkCSVData(rows: string[], chunkSize: any): string[][] {
    const chunkedData = [];
    for (let i = 0; i < rows.length; i += chunkSize) {
      chunkedData.push(rows.slice(i, i + chunkSize));
    }
    return chunkedData;
  }

  public async uploadChunk(formData: any, rowsCount: any) {
    try {
      const res: any = await super.post(api.import_master_data, formData);
      if (res.success == true) {
        if (res.success == true) {
          this.uploadState.uploadedRecords += rowsCount;
          this.uploadState.uploadProgress = `Records uploaded ${this.uploadState.uploadedRecords}/${this.uploadState.totalRecords}`;
        } else {
          const apimessage = res.message ? res.message : 'Unknown error';
          this.uploadState.uploadProgress = `Failed: ${String(apimessage)}`;
        }
      }

      if (this.checkUploadComplete()) {
        console.log('chunk Upload complete!');
      }
      return true;
    } catch (error) {
      console.log('Error Occured');
      // Optionally add retry logic here
      //this.uploadChunk( formData, rowsCount);
      throw error;
    }
  }

  checkUploadComplete() {
    return this.uploadState.totalRecords == this.uploadState.uploadedRecords;
  }

