/**
 * Storage key of the build-version baseline, scoped per bundle.
 *
 * dev/sandbox/prod serve TWO independent SPAs on ONE origin: the vesta bundle
 * at `/` and the nova bundle at `/nova/` (NOVA_BUILD=1 gives it publicPath
 * `/nova/`, see quasar.config.cjs). localStorage is shared per origin, so a
 * single `APP_VERSION` key held two different build versions (e.g. 10.86.5 and
 * 10.63.5). Every switch between the bundles looked like a version change and
 * ran a full cache cleanup. Each bundle therefore keeps its own baseline:
 * the vesta bundle keeps the historical key, any other base path gets a suffix.
 *
 * Deliberately has no imports: it is pulled into early auth/cache chunks, see
 * the note in LogoutUtil.ts.
 */
export const APP_VERSION_BASE_KEY = 'APP_VERSION';

export function versionStorageKey(
  routerBase: string | undefined = process.env.VUE_ROUTER_BASE,
): string {
  const scope = (routerBase || '/')
    .replace(/^\/+|\/+$/g, '')
    .replace(/[^A-Za-z0-9]+/g, '_');
  return scope ? `${APP_VERSION_BASE_KEY}_${scope}` : APP_VERSION_BASE_KEY;
}
