/**
 * Cache Refresh Progress Manager
 *
 * Singleton to manage progress state during cache refresh/version update.
 * Provides reactive state that can be consumed by Vue components.
 */

import { ref, readonly } from 'vue';

export interface RefreshStep {
  step: number;
  progress: number;
  message: string;
}

export const REFRESH_STEPS = {
  START: { step: 1, progress: 0, message: 'Starting update...' },
  CLEAR_LOCALSTORAGE: { step: 2, progress: 20, message: 'Clearing local storage...' },
  CLEAR_CACHES: { step: 3, progress: 40, message: 'Clearing browser caches...' },
  UNREGISTER_SW: { step: 4, progress: 60, message: 'Unregistering service workers...' },
  PREPARE: { step: 5, progress: 80, message: 'Preparing new version...' },
  RELOAD: { step: 6, progress: 100, message: 'Reloading application...' },
} as const;

// Reactive state
const isActive = ref(false);
const currentStep = ref(0);
const progress = ref(0);
const message = ref('');
const fromVersion = ref('');
const toVersion = ref('');

// DOCB-14301: set when the auto-recovery reload loop has been stopped and the
// user has to intervene (hard reload / clear site data). Mutually exclusive
// with `isActive` — a dead-end must never be presented as a running spinner.
const manualRecoveryRequired = ref(false);

// Animation state
let animationFrameId: number | null = null;
let targetProgress = 0;
const ANIMATION_SPEED = 0.15; // Progress units per frame (higher = faster)
const MICRO_PROGRESS_SPEED = 0.02; // Small continuous progress between steps

/**
 * Start the cache refresh progress overlay.
 *
 * DOCB-14301 GUARD: the overlay announces an *update*. If the version we are
 * moving to is the one we are already running, there is no update — showing
 * "v10.59.3.1 → v10.59.3.1" with a "Reloading application..." spinner is a lie
 * and, on sandbox, was the visible face of an endless reload loop. Refuse to
 * activate in that case and let the caller recover silently.
 *
 * @returns true when the overlay was actually activated.
 */
function start(from: string, to: string): boolean {
  if (from && to && from === to) {
    return false;
  }

  // Cancel any existing animation
  if (animationFrameId !== null) {
    cancelAnimationFrame(animationFrameId);
    animationFrameId = null;
  }

  manualRecoveryRequired.value = false;
  fromVersion.value = from;
  toVersion.value = to;
  currentStep.value = REFRESH_STEPS.START.step;
  progress.value = REFRESH_STEPS.START.progress;
  targetProgress = REFRESH_STEPS.START.progress;
  message.value = REFRESH_STEPS.START.message;
  isActive.value = true;
  return true;
}

/**
 * Stop the spinner and ask the user to recover manually.
 *
 * Called by the loop-breaker once automated reloads have been exhausted
 * (DOCB-14301). Clears the progress overlay so the user is never left staring
 * at a spinner that will never finish.
 *
 * @param version the build the user is stuck on. The common path never opened
 *   the overlay (a same-version recovery reload suppresses it), so `fromVersion`
 *   would otherwise be empty and the banner would read "Version unknown" —
 *   useless on a support screenshot.
 */
function requireManualRecovery(version?: string): void {
  if (animationFrameId !== null) {
    cancelAnimationFrame(animationFrameId);
    animationFrameId = null;
  }

  isActive.value = false;
  progress.value = 0;
  targetProgress = 0;
  currentStep.value = 0;
  message.value = '';
  if (version) {
    fromVersion.value = version;
  }
  manualRecoveryRequired.value = true;
}

/**
 * Dismiss the manual-recovery banner (user acknowledged it).
 */
function dismissManualRecovery(): void {
  manualRecoveryRequired.value = false;
}

/**
 * Smoothly animate progress to target value
 * Uses a combination of:
 * 1. Ease-out animation toward the target
 * 2. Continuous micro-progress to prevent "stuck" feeling
 */
function animateProgress(): void {
  if (animationFrameId !== null) {
    cancelAnimationFrame(animationFrameId);
  }

  const animate = () => {
    const current = progress.value;
    const diff = targetProgress - current;

    // If we're at or past target, just hold at target (don't overshoot)
    if (diff <= 0) {
      progress.value = targetProgress;
      // Keep animation running for continuous micro-progress when next target comes
      animationFrameId = requestAnimationFrame(animate);
      return;
    }

    // Calculate smooth step using ease-out + micro-progress
    // The micro-progress ensures there's always visible movement
    const easeStep = diff * ANIMATION_SPEED;
    const microStep = MICRO_PROGRESS_SPEED;
    const step = Math.max(easeStep, microStep);

    // Apply step and round to 1 decimal place for smooth display
    const newProgress = Math.min(targetProgress, current + step);
    progress.value = Math.round(newProgress * 10) / 10;

    animationFrameId = requestAnimationFrame(animate);
  };

  animationFrameId = requestAnimationFrame(animate);
}

/**
 * Update progress to a specific step
 */
function updateProgress(step: RefreshStep): void {
  currentStep.value = step.step;
  targetProgress = step.progress;
  message.value = step.message;

  // Start smooth animation to target
  animateProgress();
}

/**
 * Complete the refresh process
 * Immediately snaps to 100% for clean finish before reload
 */
function complete(): void {
  // Cancel any running animation
  if (animationFrameId !== null) {
    cancelAnimationFrame(animationFrameId);
    animationFrameId = null;
  }

  // Snap directly to 100% for clean finish
  currentStep.value = REFRESH_STEPS.RELOAD.step;
  targetProgress = 100;
  progress.value = 100;
  message.value = REFRESH_STEPS.RELOAD.message;
}

/**
 * Reset state (used for cleanup/testing)
 */
function reset(): void {
  // Cancel any running animation
  if (animationFrameId !== null) {
    cancelAnimationFrame(animationFrameId);
    animationFrameId = null;
  }

  isActive.value = false;
  currentStep.value = 0;
  progress.value = 0;
  targetProgress = 0;
  message.value = '';
  fromVersion.value = '';
  toVersion.value = '';
  manualRecoveryRequired.value = false;
}

/**
 * Get readonly reactive state for use in components
 */
export function useCacheRefreshProgress() {
  return {
    isActive: readonly(isActive),
    currentStep: readonly(currentStep),
    progress: readonly(progress),
    message: readonly(message),
    fromVersion: readonly(fromVersion),
    toVersion: readonly(toVersion),
    manualRecoveryRequired: readonly(manualRecoveryRequired),
    dismissManualRecovery,
  };
}

/**
 * Get mutable controls for the progress manager
 * Used by versionRefresh.ts to control the overlay
 */
export function getCacheRefreshProgressControls() {
  return {
    start,
    updateProgress,
    complete,
    reset,
    requireManualRecovery,
    dismissManualRecovery,
    STEPS: REFRESH_STEPS,
  };
}
