/**
 * CORE-6069: hover tooltips for the round icon buttons (delete / clear /
 * confirm) of the field-value popup drawn over the document image.
 *
 * That popup is built as an HTML string and appended to <body>, so a
 * <q-tooltip> component cannot be used. The buttons carry their text in
 * `data-tooltip`; `attachOverlayTooltips()` shows it after a short delay in a
 * `.q-tooltip` element, so it gets the same design-system styling as every
 * other tooltip in the app (see shadcn-theme.scss).
 */

export const OVERLAY_TOOLTIP_ID = 'overlay_button_tooltip';
export const OVERLAY_TOOLTIP_DELAY_MS = 400;
const GAP_PX = 8;

function escapeAttribute(value: string): string {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/** Attributes for a popup button: tooltip text, accessible name, test id. */
export function overlayButtonAttrs(tooltip: string, testId: string): string {
  const text = escapeAttribute(tooltip);
  return `data-tooltip="${text}" aria-label="${text}" data-test="${escapeAttribute(testId)}"`;
}

export function removeOverlayTooltip(): void {
  document.getElementById(OVERLAY_TOOLTIP_ID)?.remove();
}

function showTooltip(target: HTMLElement): void {
  removeOverlayTooltip();
  const text = target.getAttribute('data-tooltip');
  if (!text || !target.isConnected) {
    return;
  }
  const tooltip = document.createElement('div');
  tooltip.id = OVERLAY_TOOLTIP_ID;
  tooltip.setAttribute('role', 'tooltip');
  tooltip.className = 'q-tooltip q-tooltip--style no-pointer-events';
  tooltip.textContent = text;
  tooltip.style.position = 'fixed';
  tooltip.style.maxWidth = '280px';
  tooltip.style.whiteSpace = 'normal';
  tooltip.style.letterSpacing = 'normal';
  document.body.appendChild(tooltip);

  // Below the button: the popup already sits under the highlighted area, so
  // placing the tooltip further down covers neither the area nor the buttons.
  const rect = target.getBoundingClientRect();
  const width = tooltip.offsetWidth;
  const left = Math.max(
    GAP_PX,
    Math.min(
      rect.left + rect.width / 2 - width / 2,
      window.innerWidth - width - GAP_PX,
    ),
  );
  let top = rect.bottom + GAP_PX;
  if (top + tooltip.offsetHeight > window.innerHeight - GAP_PX) {
    top = rect.top - tooltip.offsetHeight - GAP_PX;
  }
  tooltip.style.left = `${left}px`;
  tooltip.style.top = `${top}px`;
}

/** Wire the tooltip behaviour to every `[data-tooltip]` element in `root`. */
export function attachOverlayTooltips(root: HTMLElement | null): void {
  if (!root) {
    return;
  }
  root.querySelectorAll<HTMLElement>('[data-tooltip]').forEach((target) => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    const hide = () => {
      if (timer) {
        clearTimeout(timer);
        timer = undefined;
      }
      removeOverlayTooltip();
    };
    target.addEventListener('mouseenter', () => {
      hide();
      timer = setTimeout(() => showTooltip(target), OVERLAY_TOOLTIP_DELAY_MS);
    });
    target.addEventListener('mouseleave', hide);
    target.addEventListener('click', hide);
  });
}
