import { Tolgee, VueTolgee, FormatSimple, LanguageStorage } from '@tolgee/vue';
import { LocalStorage } from 'quasar';
import logger from 'src/utils/logger';
import { safeBoot } from 'src/utils/bootSafety';

// Inlined to avoid importing src/constants here: that module evaluates
// i18n.t(...) at the top level, which isn't ready this early in boot (and
// breaks unit tests that import this file). These mirror src/constants.ts:
//   selected_language, DEFAULT_LANGUAGE, preferred_language_setting.
const SELECTED_LANGUAGE_KEY = 'selected_language';
const DEFAULT_LANGUAGE = 'en-us';
const PREFERRED_LANGUAGE_SETTING = 'PREFERRED_LANGUAGE';

// App language code (picker, `selected_language`, backend PREFERRED_LANGUAGE) → Tolgee language.
const TOLGEE_LANGUAGE_BY_APP_CODE = {
  'en-us': 'en', de: 'de', 'es-es': 'es', fr: 'fr', nl: 'nl', it: 'it', zh: 'zh',
  bg: 'bg', cs: 'cs', hu: 'hu', ja: 'ja', ko: 'ko', pl: 'pl', pt: 'pt', 'pt-br': 'pt-br',
  ro: 'ro', sk: 'sk', sl: 'sl', sv: 'sv', th: 'th', tr: 'tr', vi: 'vi',
};
const APP_CODE_BY_TOLGEE_LANGUAGE = Object.fromEntries(
  Object.entries(TOLGEE_LANGUAGE_BY_APP_CODE).map(([app, tolgee]) => [tolgee, app]),
);

// Languages that have translation files
const AVAILABLE_LANGUAGES = Object.keys(APP_CODE_BY_TOLGEE_LANGUAGE);

/**
 * Map any saved or browser language code to a Tolgee language.
 * App code via the map, then a Tolgee code as is, then the base language, then 'en'.
 *
 * @param {string} lang - app, Tolgee or browser language code
 * @returns {string} a code in AVAILABLE_LANGUAGES
 */
function normalizeLanguage(lang) {
  if (!lang || typeof lang !== 'string') return 'en';
  const code = lang.toLowerCase().trim().replace('_', '-');
  if (TOLGEE_LANGUAGE_BY_APP_CODE[code]) return TOLGEE_LANGUAGE_BY_APP_CODE[code];
  if (APP_CODE_BY_TOLGEE_LANGUAGE[code]) return code;
  const base = code.split('-')[0];
  if (APP_CODE_BY_TOLGEE_LANGUAGE[base]) {
    logger.tolgee(`Language '${lang}' normalized to '${base}'`);
    return base;
  }
  logger.tolgee(`Language '${lang}' not available, falling back to 'en'`);
  return 'en';
}

// Get user's language preference from our app's LocalStorage BEFORE initializing Tolgee.
// Two storage keys to consider:
//   - `selected_language` — our app's explicit user choice (set by the
//     language picker).
//   - `__tolgee_currentLanguage` — written by Tolgee's LanguageStorage
//     plugin. On first visit it picks `navigator.language` verbatim
//     (e.g. `en-us`, `pt-br`), which often doesn't match our
//     AVAILABLE_LANGUAGES list and silently renders raw keys before
//     the fallback kicks in. Normalise both and overwrite the Tolgee
//     slot up-front so the plugin reads a clean value.
const explicitSelected = LocalStorage.getItem('selected_language');
const rawLanguage =
  explicitSelected ||
  (typeof localStorage !== 'undefined'
    ? localStorage.getItem('__tolgee_currentLanguage')
    : null) ||
  (typeof navigator !== 'undefined' ? navigator.language : null) ||
  'en';
const userLanguage = normalizeLanguage(rawLanguage);

// Keep `selected_language` a valid app code; unknown values fall back with Tolgee's choice.
const appLanguage = toRegionalLanguageCode(userLanguage);
if (explicitSelected !== appLanguage) {
  try {
    LocalStorage.set(SELECTED_LANGUAGE_KEY, appLanguage);
  } catch {
    // Storage can be blocked; the in-memory language still applies.
  }
}
// Sanity-overwrite: if Tolgee's own slot holds a non-available value
// (the classic `en-us` / `en-gb` case), replace it with the normalised
// equivalent so subsequent Tolgee reads never see an invalid code.
try {
  if (typeof localStorage !== 'undefined') {
    const stored = localStorage.getItem('__tolgee_currentLanguage');
    if (stored && !AVAILABLE_LANGUAGES.includes(stored.toLowerCase())) {
      localStorage.setItem('__tolgee_currentLanguage', userLanguage);
    }
  }
} catch {
  // LocalStorage access can throw on strict privacy settings — non-fatal.
}
logger.tolgee(
  'User language preference (selected_language / __tolgee_currentLanguage):',
  rawLanguage,
  '→ normalized to:',
  userLanguage,
);

// Loader map shared by both `staticData` (Tolgee's lazy contract) and
// the explicit pre-load step in safeBoot below. Defining the imports
// here once means the Vite static-analyser still picks them all up
// (so each locale lands in its own code-split chunk) AND we can
// invoke them eagerly when needed.
//
// Bug-2026-05-04: on dev (post `restore production app mount` deploy)
// Tolgee's lazy staticData path entered an inconsistent state — the
// import promise for `en` resolved, `isLoaded()` flipped to true, but
// `getRecord('en')` stayed empty and every `t()` call returned the
// raw key. Live forensics confirmed: feeding the same JSON via
// `addStaticData()` after init populated the record correctly. The
// safeBoot wrapper below now forces that path on every boot for the
// user's language (CORE-6327: the `en` fallback is merged into each
// dictionary at build time, so it is no longer a second download).
const STATIC_DATA_LOADERS = {
  en: () => import('src/tolgee/i18n/en.json').then(m => m.default || m),
  de: () => import('src/tolgee/i18n/de.json').then(m => m.default || m),
  it: () => import('src/tolgee/i18n/it.json').then(m => m.default || m),
  fr: () => import('src/tolgee/i18n/fr.json').then(m => m.default || m),
  es: () => import('src/tolgee/i18n/es.json').then(m => m.default || m),
  nl: () => import('src/tolgee/i18n/nl.json').then(m => m.default || m),
  zh: () => import('src/tolgee/i18n/zh.json').then(m => m.default || m),
  bg: () => import('src/tolgee/i18n/bg.json').then(m => m.default || m),
  cs: () => import('src/tolgee/i18n/cs.json').then(m => m.default || m),
  hu: () => import('src/tolgee/i18n/hu-HU.json').then(m => m.default || m),
  ja: () => import('src/tolgee/i18n/ja.json').then(m => m.default || m),
  ko: () => import('src/tolgee/i18n/ko-KR.json').then(m => m.default || m),
  pl: () => import('src/tolgee/i18n/pl.json').then(m => m.default || m),
  pt: () => import('src/tolgee/i18n/pt.json').then(m => m.default || m),
  'pt-br': () => import('src/tolgee/i18n/pt-BR.json').then(m => m.default || m),
  ro: () => import('src/tolgee/i18n/ro.json').then(m => m.default || m),
  sk: () => import('src/tolgee/i18n/sk.json').then(m => m.default || m),
  sl: () => import('src/tolgee/i18n/sl.json').then(m => m.default || m),
  sv: () => import('src/tolgee/i18n/sv.json').then(m => m.default || m),
  th: () => import('src/tolgee/i18n/th.json').then(m => m.default || m),
  tr: () => import('src/tolgee/i18n/tr.json').then(m => m.default || m),
  vi: () => import('src/tolgee/i18n/vi.json').then(m => m.default || m),
};

// ⭐ FIX: Initialize Tolgee with proper async loading to prevent missing key warnings
// Use staticData with optional missingKeyHandler to suppress warnings in build/test environments
const tolgee = Tolgee()
  .use(FormatSimple())
  .use(LanguageStorage())
  .init({
    availableLanguages: AVAILABLE_LANGUAGES,
    defaultLanguage: userLanguage, // Use user's language as default
    // CORE-6327: no runtime fallbackLanguage. Tolgee treats every fallback
    // language as a REQUIRED record, and <TolgeeProvider> in App.vue renders
    // nothing until all required records are loaded — so `fallbackLanguage:
    // 'en'` made every non-English user download en (~276 KB br) before first
    // paint. The fallback now happens at build time instead:
    // plugins/vite-tolgee-fallback-merge.cjs fills every key a dictionary lacks
    // with the English text, so each <lang>.json is complete on its own.
    staticData: STATIC_DATA_LOADERS,
    // Suppress missing key warnings during build/test - translation exists but loading is async
    // In dev/prod with proper async loading, this handler won't be triggered
    // FIX: Use import.meta.env.MODE instead of process.env.NODE_ENV (works in all build modes)
    missingKeyHandler: import.meta.env.MODE === 'test'
      ? 'silent'
      : import.meta.env.DEV
        ? (key) => { console.warn(`[i18n] Missing translation key: "${key.key}"`); }
        : undefined,
  });

// Eagerly load + register a single locale via addStaticData. Safe to
// call multiple times (Tolgee deduplicates on language+namespace).
async function _eagerLoad(lang) {
  const loader = STATIC_DATA_LOADERS[lang];
  if (!loader) return false;
  try {
    const data = await loader();
    if (data && typeof data === 'object') {
      tolgee.addStaticData({ [lang]: data });
      return true;
    }
  } catch (e) {
    logger.tolgee(`Eager staticData load failed for ${lang}:`, e);
  }
  return false;
}

// Quasar's built-in texts (date-picker names...) follow the UI language. The
// pack table lives in its own lazy chunk: it must not count against the boot
// budget, and a failed download must never break a language switch.
function applyQuasarLang(lang) {
  return Promise.all([
    import('src/utils/quasar-lang').then((m) => m.applyQuasarLang(lang)),
    import('src/utils/dateFnsLocale').then((m) => m.applyDateLocale(lang)),
  ]).catch((e) => logger.tolgee(`Quasar/date locale skipped for ${lang}:`, e));
}

// Runtime language switch: register the dictionary before switching, en if it fails.
export async function switchLanguage(lang) {
  let target = lang;
  if (!(await _eagerLoad(lang)) && lang !== 'en' && (await _eagerLoad('en'))) target = 'en';
  await tolgee.changeLanguage(target);
  void applyQuasarLang(target);
  return target;
}

export default safeBoot('tolgee', async ({ app }) => {
  // Bug-2026-05-04 fix: explicitly preload the user's language BEFORE
  // `app.use(VueTolgee, ...)` so the first render has a populated record.
  // Without this the staticData lazy callback can hand Tolgee the JSON but
  // the record never gets committed (observed live: `isLoaded()=true` +
  // `getRecord('en')` returning empty + every `t()` falling back to the
  // raw key).
  //
  // CORE-6327: only the user's language. It used to be `en` first and then
  // the user's language, one after the other — two full dictionaries in
  // front of first paint. Every non-English dictionary already contains the
  // English text for the keys it lacks (build-time merge, see init above),
  // so `en` is not needed unless it IS the user's language.
  let activeLanguage = userLanguage;
  const loaded = await _eagerLoad(userLanguage);
  if (!loaded && userLanguage !== 'en' && (await _eagerLoad('en'))) {
    // The user's dictionary failed to download (chunk error, offline...).
    // English beats a screen of raw keys; the next boot tries again.
    activeLanguage = 'en';
  }

  app.use(VueTolgee, { tolgee });

  // Use tolgee.t() directly instead of useTranslate()
  app.config.globalProperties.tt = (key, params) => tolgee.t(key, params);

  // `$i18n.locale` used to come from vue-i18n (removed in CORE-6332), whose
  // locale was the browser language and never followed the user's choice.
  // Components still read it to pick the language of bilingual API text, so
  // keep the property and answer with Tolgee's active base language instead.
  app.config.globalProperties.$i18n = Object.freeze({
    get locale() {
      return String(tolgee.getLanguage?.() || 'en').split('-')[0];
    },
  });

  // Belt-and-suspenders: force the language to the normalised value
  // right after init. If LanguageStorage previously wrote `en-us` (or
  // similar regional variant) before we added the sanity-overwrite
  // above, this ensures the live runtime uses the clean code even on
  // existing sessions. Safe on fresh sessions too.
  try {
    const current = tolgee.getLanguage?.();
    if (current !== activeLanguage) {
      await tolgee.changeLanguage(activeLanguage).catch(() => {});
    }
  } catch {
    // If the runtime doesn't support changeLanguage in this phase, the
    // defaultLanguage passed to init() still applies.
  }

  // Date-picker names and other Quasar built-ins follow the UI language.
  // Lazy and not awaited: first paint must not wait for it.
  void applyQuasarLang(activeLanguage);

  // Log successful Tolgee initialization
  logger.tolgee('Tolgee initialized with language:', activeLanguage);

  // Returning-user restore: if an auth token is already present at boot
  // (refresh / re-open while logged in), apply the user's backend
  // PREFERRED_LANGUAGE. Fire-and-forget on purpose — must not delay first
  // paint, and the settings store is dynamically imported so it stays out of
  // the boot/entry chunk (see CLAUDE.md "Build Optimization"). Fresh logins,
  // where the token arrives AFTER boot, are covered by the post-login reload.
  void restoreBackendLanguage();
});

async function restoreBackendLanguage() {
  try {
    const tokenDetails = LocalStorage.getItem('token_details');
    if (!tokenDetails || !tokenDetails.access_token) return; // not logged in at boot
    // DRDG-16: on token intake the stored token is the previous session's; the intake page loads settings itself.
    if (isTokenIntakePath(window.location.pathname)) return;

    const { useSettingStore } = await import('src/store/Settings/setting.store');
    const settingsStore = useSettingStore();
    await settingsStore.startSettingsFetch();
    const backendLanguage = await settingsStore.getUserBasedSettings(PREFERRED_LANGUAGE_SETTING);
    if (!backendLanguage) return; // no server preference saved

    const base = normalizeLanguage(backendLanguage);
    LocalStorage.set(SELECTED_LANGUAGE_KEY, toRegionalLanguageCode(base));
    if (tolgee.getLanguage?.() !== base) {
      await switchLanguage(base);
    }
    logger.tolgee('Restored backend language:', backendLanguage, '-> Tolgee:', base);
  } catch (e) {
    // Non-fatal: boot already applied a sensible default language.
    logger.tolgee('Backend language restore skipped:', e);
  }
}

export function isTokenIntakePath(pathname) {
  return /\/(auth|token-login)(\/|$)/.test(pathname || '');
}

export const tol = tolgee;

/**
 * Map a Tolgee language back to the app code the picker and backend use ('en' → 'en-us').
 *
 * @param {string|null|undefined} code - language code from tolgee.getLanguage()
 * @returns {string} the app code, or DEFAULT_LANGUAGE if empty or unknown
 */
export function toRegionalLanguageCode(code) {
  return APP_CODE_BY_TOLGEE_LANGUAGE[normalizeLanguage(code)] || DEFAULT_LANGUAGE;
}

// Export for testing
export { normalizeLanguage, AVAILABLE_LANGUAGES };
