/**
 * CORE-6333 — start the telemetry SDKs after the first render.
 *
 * Quasar awaits every boot file before app.mount(), so a boot file that
 * imports @sentry/vue or @grafana/faro-* statically puts those SDKs (and the
 * OpenTelemetry code behind Faro's tracing) in front of the login page. The
 * `sentry` and `faro` boot files instead call runAfterFirstRender() with an
 * import() of src/utils/telemetry/sentry-sdk.ts / faro-sdk.ts.
 *
 * Errors raised before Sentry is up (window, Vue and router errors) are kept
 * by createEarlyErrorBuffer() and handed to Sentry when it starts. For Faro,
 * the inline PREBOOT ERROR BRIDGE in index.html records every window error and
 * rejection, and src/boot/faro.ts queues router errors, events and
 * measurements until faro-sdk.ts flushes them.
 *
 * scripts/check-boot-telemetry.cjs fails the build when an SDK is back on
 * the render path.
 */
import type { App } from 'vue';
import type { Router } from 'vue-router';

/** How long to wait for an idle period after `load` before running anyway. */
export const TELEMETRY_IDLE_TIMEOUT_MS = 2500;

/**
 * Run `task` once the page has fired `load` and the main thread is idle
 * (or after `timeoutMs`, whichever comes first). Never throws.
 */
export function runAfterFirstRender(
  task: () => void,
  timeoutMs: number = TELEMETRY_IDLE_TIMEOUT_MS,
): void {
  const run = () => {
    try {
      task();
    } catch (err) {
      console.warn('[Telemetry] Deferred init failed:', err);
    }
  };
  if (typeof window === 'undefined') {
    run();
    return;
  }
  const whenIdle = () => {
    if (typeof window.requestIdleCallback === 'function') {
      window.requestIdleCallback(run, { timeout: timeoutMs });
    } else {
      // Safari has no requestIdleCallback.
      setTimeout(run, 1);
    }
  };
  if (document.readyState === 'complete') {
    whenIdle();
  } else {
    window.addEventListener('load', whenIdle, { once: true });
  }
}

export interface EarlyError {
  kind: 'error' | 'unhandledrejection' | 'vue' | 'router';
  error: unknown;
  /** Vue lifecycle hook for `kind: 'vue'`. */
  info?: string;
}

export interface EarlyErrorBuffer {
  /** Stop buffering, restore the Vue error handler and return what was caught. */
  drain(): EarlyError[];
}

const MAX_EARLY_ERRORS = 50;

/**
 * Buffer window errors, unhandled rejections, Vue component errors and router
 * errors (vue-router swallows a failed first navigation) until the SDK is ready. The Vue handler that was installed before (main.js) keeps
 * running for every error; drain() puts it back so the SDK wraps it, not the
 * buffer.
 */
export function createEarlyErrorBuffer(
  app?: App,
  router?: Router,
): EarlyErrorBuffer {
  const buffer: EarlyError[] = [];
  const push = (entry: EarlyError) => {
    if (buffer.length < MAX_EARLY_ERRORS) buffer.push(entry);
  };

  const onError = (event: ErrorEvent) =>
    push({ kind: 'error', error: event.error ?? event.message });
  const onRejection = (event: PromiseRejectionEvent) =>
    push({ kind: 'unhandledrejection', error: event.reason });

  window.addEventListener('error', onError);
  window.addEventListener('unhandledrejection', onRejection);

  const stopRouterErrors = router?.onError((error) =>
    push({ kind: 'router', error }),
  );

  const previousHandler = app?.config.errorHandler;
  if (app) {
    app.config.errorHandler = (err, instance, info) => {
      push({ kind: 'vue', error: err, info });
      if (previousHandler) {
        previousHandler(err, instance, info);
      } else {
        console.error(err);
      }
    };
  }

  let drained = false;
  return {
    drain() {
      if (!drained) {
        drained = true;
        window.removeEventListener('error', onError);
        window.removeEventListener('unhandledrejection', onRejection);
        stopRouterErrors?.();
        if (app) app.config.errorHandler = previousHandler;
      }
      return buffer.splice(0);
    },
  };
}
