import { computed, ref } from 'vue';

/**
 * The backend treats any validate_and_export on a document parked for approval
 * as the approval itself, so a duplicate submit while the first request is
 * still in flight silently bypasses the approval gate. Every export request
 * runs through here, keyed by document: a second call for the same document
 * joins the request already running instead of sending its own, and both
 * callers see the same response.
 */
const requests_in_flight = ref(new Map<string, Promise<any>>());

/** Drives the disabled state of the export buttons. */
export const export_request_in_flight = computed(
  () => requests_in_flight.value.size > 0,
);

export function runExportRequest<T>(
  doc_id: string,
  sendRequest: () => Promise<T>,
): Promise<T> {
  const running = requests_in_flight.value.get(doc_id);
  if (running) {
    return running as Promise<T>;
  }

  const request = sendRequest().finally(() => {
    requests_in_flight.value.delete(doc_id);
  });
  requests_in_flight.value.set(doc_id, request);

  return request;
}
