// E-Invoice validation rules catalog (BOL-414 / BOL-417).
// Mirrors the GET / PUT contract from
// doc2-api/routers/electronic_document/router.py.

import AbstractApiService from 'src/services/abstractApiService';
import { api } from 'pages/APIs';

export type RuleSeverity = 'fatal' | 'error' | 'warning' | 'info';

export type RuleLayer = 'L0' | 'L0b' | 'L0c' | 'L1' | 'L2' | 'L3' | 'L4';

export interface ValidationRuleRow {
  code: string;
  layer: RuleLayer;
  profile: string; // XRECHNUNG | EN16931 | PRE_XML | DEMO | ANY | …
  version: string | null;
  field: string | null;
  default_severity: RuleSeverity;
  effective_severity: RuleSeverity;
  override: RuleSeverity | null;
  // BOL-424 detail fields. Populated for L4 in-house codes (IBAN
  // family); null/empty for KoSIT-extracted L3 rules and the simpler
  // L0/L0b/L1/L2 codes where they don't apply.
  field_label: string | null;
  description: string | null;
  method: string | null;
  triggered_when: string | null;
  example_valid: string | null;
  example_invalid: string | null;
  references: string[];
  // BOL-424 rationale: every row carries a "why this rule exists"
  // string (per-rule for in-house codes, layer-fallback for KoSIT
  // codes) so admins can decide whether to override safely.
  rationale: string | null;
}

// BOL-429: per-org acceptance policy registry.
export interface VersionRegistryEntry {
  version: string; // "3.0.2" | "3.0" | "2.3" | …
  label: string;
  status: 'current' | 'deprecated' | 'eol';
  released_on: string | null;
  note: string | null;
  has_bundle: boolean;
}

export interface ProfileRegistryEntry {
  profile: 'MINIMUM' | 'BASIC_WL' | 'BASIC' | 'EN16931' | 'EXTENDED' | 'XRECHNUNG';
  label: string;
  en16931_conformant: boolean;
  note: string | null;
}

export interface ValidationVersionsResponse {
  success: boolean;
  versions: VersionRegistryEntry[];
  profiles: ProfileRegistryEntry[];
}

export interface ListParams {
  keyword?: string;
  layer?: string | null;
  profile?: string | null;
  versions?: string[];
  only_overridden?: boolean;
  skip?: number;
  limit?: number;
  sort_by?: string | null;
  order?: 'asc' | 'desc';
}

export interface RulesFacets {
  profiles: string[];
  versions: string[];
  catalog_total: number;
  override_count: number;
}

export interface ValidationRulesListResponse {
  success: boolean;
  metadata: { total_results: number; skip: number; limit: number | null };
  data: ValidationRuleRow[];
  facets: RulesFacets;
}

export interface ValidationPolicyRow {
  doc_type: string;
  enabled: boolean;
  blocking: boolean;
  has_subtype_overrides: boolean;
}
export interface ValidationChangeEntry {
  id: string;
  at: string;
  user_id: string;
  user_name: string | null;
  rule_code: string | null;
  old_level: string | null;
  new_level: string | null;
  action: 'set' | 'delete' | 'wizard';
  details: unknown;
}

export default class ValidationRulesApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  public async getValidationPolicy(): Promise<{
    success: boolean;
    rows: ValidationPolicyRow[];
  }> {
    return super.get(api.einvoice_validation_policy);
  }

  public async setValidationPolicy(
    docType: string,
    changes: Partial<Pick<ValidationPolicyRow, 'enabled' | 'blocking'>>,
  ): Promise<ValidationPolicyRow & { success: boolean }> {
    return super.put(
      `${api.einvoice_validation_policy}/${encodeURIComponent(docType)}`,
      changes,
      { skipOrgId: true },
    );
  }

  public async changeLog(
    offset = 0,
    limit = 50,
  ): Promise<{
    success: boolean;
    entries: ValidationChangeEntry[];
    limit: number;
    offset: number;
  }> {
    return super.get(
      `${api.einvoice_validation_rules}/change_log?limit=${limit}&offset=${offset}`,
    );
  }

  public async list(params: ListParams = {}): Promise<ValidationRulesListResponse> {
    const qs = new URLSearchParams();
    const keyword = (params.keyword || '').trim();
    if (keyword) qs.append('keyword', keyword);
    if (params.layer) qs.append('layer', params.layer);
    if (params.profile) qs.append('profile', params.profile);
    const versions = (params.versions || []).filter(Boolean);
    if (versions.length) qs.append('versions', versions.join(','));
    if (params.only_overridden) qs.append('only_overridden', 'true');
    if (params.limit) qs.append('limit', String(params.limit));
    if (params.skip) qs.append('skip', String(params.skip));
    if (params.sort_by) {
      qs.append('sort_by', params.sort_by);
      qs.append('order', params.order || 'asc');
    }
    const url =
      qs.toString().length > 0
        ? `${api.einvoice_validation_rules}?${qs.toString()}`
        : api.einvoice_validation_rules;
    return super.get(url);
  }

  public async clearAllOverrides(): Promise<{ success: boolean; cleared: number }> {
    return super.delete(`${api.einvoice_validation_rules}/overrides`, {});
  }

  /** Set or clear a per-org severity override.
   *  Pass `severity = null` (or empty) to clear and revert to KoSIT default. */
  public async setOverride(
    code: string,
    severity: RuleSeverity | null,
  ): Promise<{ success: boolean; rule_code: string; severity: string | null }> {
    const formData = new FormData();
    if (severity) formData.append('severity', severity);
    return super.put(
      `${api.einvoice_validation_rule_severity}/${encodeURIComponent(code)}/severity`,
      formData,
    );
  }

  /** Fetch the supported XRechnung version + ZUGFeRD profile registries.
   *  Drives the BOL-429 acceptance-policy section. */
  public async listVersions(): Promise<ValidationVersionsResponse> {
    return super.get(api.einvoice_validation_versions);
  }
}
