// Rule execution logs — the audit trail the three rule engines write. One row
// is one evaluation of one rule against one document, so a single document run
// leaves entries behind from the validation, transformation and layout-selection
// families alike.
//
// GET /rule-execution-logs?rule_type=validation&skip=0&limit=50
//
// Every parameter is optional and every one narrows the same listing, so the
// rule family alone is a valid query — it returns that family's whole trail,
// paged. rule_id / rule_key / doc_id are filters like any other, not a
// required selector.

import AbstractApiService from 'src/services/abstractApiService';
import { api } from 'pages/APIs';

/** The three rule families sharing the log table. */
export type RuleFamily = 'validation' | 'transformation' | 'layout_selection';

/** Every outcome across the three families. Which ones can occur depends on
 *  rule_type: passed/failed/skipped for validation, applied/no_change/skipped
 *  for transformation, matched/not_matched for layout selection. */
export type RuleOutcome =
  | 'passed'
  | 'failed'
  | 'skipped'
  | 'applied'
  | 'no_change'
  | 'matched'
  | 'not_matched';

/** One evaluation of one rule against one document.
 *  rule_type / outcome stay plain strings: the engines may write a value this
 *  build's union does not know yet, and it must still be readable. */
export interface RuleExecutionLog {
  id: string;
  rule_type: string;
  rule_id: string;
  rule_key: string;
  doc_type: string | null;
  doc_id: string | null;
  scope: string | null;
  target_field: string | null;
  row_index: number | null;
  outcome: string;
  executed: boolean;
  severity: string | null;
  // Free-form payload the engine attached (expected/actual, conditions,
  // input/output values, matched layout …) — shape depends on rule_type.
  details: unknown;
  created_by: number | null;
  created_by_name: string | null;
  created_on: string | null;
}

/** A page of entries plus the unpaged total for the same filters. */
export interface RuleExecutionLogPage {
  data: RuleExecutionLog[];
  total: number;
  skip: number;
  limit: number;
}

/** Query for GET /rule-execution-logs. Empty strings / null are dropped, so
 *  an "Any" filter can be passed straight through. */
export interface RuleExecutionLogQuery {
  // Narrowing filters, all optional and combinable.
  rule_id?: string;
  rule_key?: string;
  doc_id?: string;
  // One run writes entries from all three families, so this is what separates
  // them when reading a document's trail.
  rule_type?: RuleFamily | '';
  doc_type?: string;
  outcome?: RuleOutcome | '';
  // True: the rule's logic ran. False: its condition excluded it.
  executed?: boolean | null;
  from_date?: string;
  to_date?: string;
  skip?: number;
  limit?: number;
}

export default class RuleExecutionLogsApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  /** A page of log entries, newest first. The org travels in the x-org-id
   *  header, so org_id must NOT be appended to the query string. */
  public async list(
    query: RuleExecutionLogQuery,
  ): Promise<RuleExecutionLogPage> {
    const params = new URLSearchParams();
    Object.entries(query).forEach(([key, value]) => {
      if (value === undefined || value === null || value === '') {
        return;
      }
      params.append(key, String(value));
    });
    const queryString = params.toString();
    const url = queryString
      ? `${api.rule_execution_logs}?${queryString}`
      : api.rule_execution_logs;
    return super.getWithoutOrgId(url);
  }
}
