import { tol } from 'src/boot/tolgee';

/**
 * Translation entry point for plain TS/JS modules.
 *
 * Not a Quasar boot file any more: vue-i18n was removed (CORE-6332) and
 * Tolgee (src/boot/tolgee.js) is the only translation system. This module
 * stays so the existing `import { i18n } from 'src/boot/i18n'` call sites keep
 * working; `i18n` IS the Tolgee instance.
 *
 * - Templates / Options API: `$t('key', params)` (Tolgee's VueTolgee plugin)
 * - setup() / composables: `useTranslate()` from '@tolgee/vue'
 * - plain modules: `i18n.t('key', params)`
 */
export const i18n = tol;
