/**
 * Response type for WatchDog service status endpoint
 */
export interface WatchdogStatusResponse {
  success: boolean;
  online: boolean;
  last_seen: string | null;
  last_restart: string | null;
  has_pending_commands: boolean;
  version?: string;                        // Current installed version
  version_first_seen?: string | null;      // ISO timestamp when version first seen
  auto_update_enabled?: boolean | null;    // Auto-update setting
  auto_update_check_interval?: number;     // Update check interval in seconds
  latest_version?: string | null;          // Latest version from GitHub
  latest_version_checked_at?: string | null; // When latest version was checked
  installation_path?: string | null;       // Installation directory path
  free_ram_bytes?: number | null;          // Available RAM in bytes
  free_disk_bytes?: number | null;         // Free disk space in bytes
  message?: string;
}

/**
 * Response type for WatchDog command creation endpoint
 */
export interface CreateCommandResponse {
  success: boolean;
  id?: string;
  command_type?: string;
  status?: string;
  created_at?: string;
  message?: string;
}

