  async getFlowToken(configuration: any): Promise<any> {
    const data = {
      username: configuration.username,
      password: configuration.password,
    };
    const url =
      configuration.export_url.replace(/\/+$/, '') +
      '/api/v4/auth/token/obtain/';

    const options = {
      error: this.handleFlowTokenError.bind(this),
    };

    const formData = new FormData();
    for (const [key, value] of Object.entries(data)) {
      formData.append(key, String(value));
    }

    return super.post(url, formData, options);
  }

  protected handleFlowTokenError(error: unknown): any {
    if (!(error instanceof Error)) {
      super.handleError(error);
    }
    if (error instanceof Error && error.message == 'Network Error') {
      throw new Error('Invalid url, Please check.');
    }

    if (
      this.isAxiosError(error) &&
      error.response &&
      error.response.status &&
      error.response.status === 400
    ) {
      throw new Error('Invalid credentials, Please check.');
    }

    super.handleError(error);
  }

