  /**
   * Create/upload a new XSLT template for Watchdog.
   * @param file - The XSLT file to upload
   */
  public async createWatchdogTemplate(file: File): Promise<any> {
    // Read file content and send as JSON (backend expects JSON, not FormData)
    const content = await file.text();
    // Remove .xslt or .xsl extension from filename for template name
    const name = file.name.replace(/\.(xslt?|xsl)$/i, '');
    return super.post(api.watchdog_templates, { name, content });
  }

  /**
   * Get export execution logs for a document.
   * @param docId - The document ID
   * @param options - Query options
   */
  public async getExportLogs(
    docId: string,
    options: {
      includeSkipped?: boolean;
      includeDeleted?: boolean;
      limit?: number;
      offset?: number;
    } = {},
  ): Promise<any> {
    const params = new URLSearchParams();
    params.append('include_skipped', String(options.includeSkipped ?? true));
    params.append('include_deleted', String(options.includeDeleted ?? false));
    params.append('limit', String(options.limit ?? 100));
    params.append('offset', String(options.offset ?? 0));

    return super.get(`${api.export_logs}${docId}?${params.toString()}`);
  }
