import { useUserStore } from 'src/store/User/user_details.store';
import { SessionStorage, LocalStorage } from 'quasar';
import { getUserDetails } from 'src/utils/UserDetails';

/** An organisation entry as it appears on `user_details.organisations`. */
interface StoredOrganisation {
  org_id?: string;
  id?: string;
  is_default?: boolean;
}

function orgIdOf(entry?: StoredOrganisation | null): string {
  // Both keys occur: `UserOrg.set()` normalises the flat sub-org response
  // into `{ id, ... }`, while the wrapped `{ organisations: [...] }`
  // response is passed through carrying `org_id`.
  return entry?.org_id || entry?.id || '';
}

/**
 * The organisation the ACCESS TOKEN is scoped to, from `token_details` —
 * written by `setTokenInLocalStorage` out of the select/switch-organisation
 * response, and stored in LocalStorage so it survives a new tab.
 *
 * Consulted before the legacy top-level `user_details.org_id`: during an
 * organisation switch the token is updated to org B while the shared profile
 * may still carry org A, and trusting the profile there would send org A
 * with a B-scoped token and trip the backend's org/token mismatch guard.
 *
 * Absent after a plain token refresh — `OAuth2TokenResponse` carries no
 * `org_id` and overwrites `token_details`.
 */
function getTokenOrgId(): string {
  try {
    const tokenDetails = LocalStorage.getItem('token_details') as {
      org_id?: string;
    } | null;
    return tokenDetails?.org_id ? String(tokenDetails.org_id) : '';
  } catch {
    return '';
  }
}

/**
 * The organisation id when the user belongs to exactly ONE, read from
 * `user_details.organisations`.
 *
 * DRFS-743: the legacy fallback scans `user_details` for a TOP-LEVEL
 * `org_id`, which the profile shape this app stores does not have — its
 * top-level keys are `_cache, organisations, subscription, total_sub_orgs,
 * user, id, is_organisation_admin, first_name, last_name`. So with no
 * `active_org_id` in sessionStorage every caller got '' although the
 * organisation was in LocalStorage all along. That is how the WebSocket
 * connects as `/ws/v2?org_id=` and the dashboard renders zero rows.
 *
 * Deliberately limited to a SINGLE membership. `organisations` lists every
 * membership in no guaranteed order, and after a refresh the token source
 * above is gone — so for a multi-org user any pick (first entry,
 * `is_default`) could contradict the token. A wrong organisation is worse
 * than none: '' leaves the caller knowingly without one, a wrong id
 * produces confident, failing requests. Carrying the active org across
 * refreshes needs it persisted alongside the token, which is a change to
 * the auth flow rather than to this resolver.
 */
function getSoleOrganisationId(): string {
  try {
    const details = getUserDetails() as {
      organisations?: StoredOrganisation[];
    };
    const organisations = details?.organisations;
    if (!Array.isArray(organisations) || organisations.length !== 1) return '';
    return orgIdOf(organisations[0]);
  } catch {
    // This reads LocalStorage; never let it break org resolution.
    return '';
  }
}

export function getOrgId() {
  // CRITICAL FIX: Check SessionStorage FIRST (survives clearAllStorage during login flow)
  // SessionStorage is set by authSdkService.setSessionUser() and protected from clearAllStorage
  // This ensures org_id is available immediately after login, even if LocalStorage is temporarily cleared

  // Try Quasar's SessionStorage wrapper first
  let sessionOrgId = SessionStorage.getItem('active_org_id') as string | null;

  // BUGFIX: If Quasar wrapper returns null, try native sessionStorage
  // This handles cases where Quasar's wrapper has issues
  if (!sessionOrgId && typeof window !== 'undefined' && window.sessionStorage) {
    sessionOrgId = window.sessionStorage.getItem('active_org_id');
  }

  if (sessionOrgId) {
    return sessionOrgId.replace(/\s/g, '');
  }

  // DRFS-743 (Codex round 3): the token-scoped organisation is checked
  // BEFORE the legacy top-level value. During an organisation switch
  // `token_details` is updated to org B while the shared profile may still
  // carry org A at its top level; trusting the profile first would send org
  // A with a B-scoped token and trip the backend's mismatch guard.
  const tokenOrgId = getTokenOrgId();
  if (tokenOrgId) {
    return tokenOrgId.replace(/\s/g, '');
  }

  // Fallback to LocalStorage via user store (for persistence across sessions if needed)
  const user_store = useUserStore();
  const org_id = user_store.getOrgId();

  if (org_id) {
    return org_id.replace(/\s/g, '');
  }

  // DRFS-743: the fallback above looks for a TOP-LEVEL `org_id` on
  // `user_details`, and the profile shape this app actually stores does not
  // have one. Its top-level keys are `_cache, organisations, subscription,
  // total_sub_orgs, user, id, is_organisation_admin, first_name, last_name`
  // — the organisation lives at `organisations[0].org_id`. So whenever
  // sessionStorage has no `active_org_id`, every caller of this helper got
  // '' even though the organisation was sitting in LocalStorage all along.
  //
  // That is how the WebSocket ends up connecting as `/ws/v2?org_id=` and the
  // dashboard renders zero rows: sessionStorage is per-tab and starts empty
  // in any context that did not perform the login itself.
  const soleOrgId = getSoleOrganisationId();
  if (soleOrgId) {
    return soleOrgId.replace(/\s/g, '');
  }

  // Only warn if user is authenticated (has a token) - rate limited to once per minute
  // Check for window existence (not available in Node.js test environments)
  if (process.env.DEV && typeof window !== 'undefined') {
    const now = Date.now();
    const lastWarn = (window as any).__orgIdHelperLastWarn || 0;
    if (now - lastWarn > 60000) {
      const tokenDetails = LocalStorage.getItem('token_details') as any; // Note: typo is intentional
      const isAuthenticated = tokenDetails?.access_token;
      if (isAuthenticated) {
        console.warn('[ORG_ID_HELPER] No org_id found in SessionStorage or user store');
        (window as any).__orgIdHelperLastWarn = now;
      }
    }
  }

  return org_id;
}

export function hasValidOrgId(): boolean {
  const org_id = getOrgId();
  return !!(
    org_id &&
    org_id.trim() !== '' &&
    org_id !== 'null' &&
    org_id !== 'undefined'
  );
}

export function addOrgIdToUrl(url: string) {
  const org_id = getOrgId();
  if (org_id) {
    url = url.replace('{org_id}', org_id);
  }
  return url;
}

export function addOrgIdQueryString(url: string) {
  const org_id = getOrgId();
  if (!org_id) {
    return url;
  }

  const orgIdRegex = /[?&]org_id=[^&]*/;
  const match = orgIdRegex.exec(url);

  if (match !== null) {
    return url;
  } else if (url.includes('?')) {
    return url + '&org_id=' + org_id;
  } else {
    return url + '?org_id=' + org_id;
  }
}
