import { api } from 'pages/APIs';
import type { dynamicObj } from 'src/pages/assets';
import { isUndefinedOrNull } from 'src/utils/general';
import AbstractApiService from 'src/services/abstractApiService';
import axios, { CanceledError, type AxiosAdapter } from 'axios';
import { watch, type WatchStopHandle } from 'vue';
import { useUserIdentityVersion } from 'src/utils/user-identity';

export interface TaskMutationOwner {
  readonly signal?: AbortSignal;
  readonly isCurrent?: () => boolean;
}

export default class TaskApiService extends AbstractApiService {
  public constructor({}) {
    super({});
  }

  public async getTasks(params: dynamicObj): Promise<any> {
    return this.getTaskList(params);
  }
  public async getTaskList(params: dynamicObj): Promise<any> {
    const querystring = this.encodeQueryData(params);
    return super.get(api.api_task + '?' + querystring, {});
  }

  public async getTotalTaskCount(params: dynamicObj): Promise<any> {
    const querystring = this.encodeQueryData(params);
    return super.get(api.api_total_tasks_count + '?' + querystring, {});
  }

  public async getTaskById(id: string, use_cache = true): Promise<any> {
    let cache = use_cache.toString();
    cache = cache.charAt(0).toUpperCase() + cache.slice(1);
    cache = `?cache=${cache}`;
    return super.get(api.api_task + '/by-id/' + id + cache, {});
  }

  public async createTask(data: dynamicObj): Promise<any> {
    const api_data: any = {};
    for (const [key, value] of Object.entries(data)) {
      api_data[key] = String(value);
    }
    return super.post(api.api_task, api_data);
  }

  public async deleteTask(id: string, owner?: TaskMutationOwner): Promise<any> {
    return this.deleteOwnedTask(api.api_task + '/by-id/' + id, {}, owner);
  }
  public async bulkDeleteTasks(task_ids: string[], owner?: TaskMutationOwner): Promise<any> {
    const form = new FormData();
    form.append('task_ids', task_ids.join(','));
    return this.deleteOwnedTask(api.api_task, form, owner);
  }

  private async deleteOwnedTask(
    path: string,
    payload: FormData | dynamicObj,
    owner?: TaskMutationOwner,
  ): Promise<any> {
    // Capture before token refresh or any other await. Each mutation owns its
    // own scope; another valid mutation or a list read must not supersede it.
    const orgId = this.getOrgId();
    const identityVersion = useUserIdentityVersion();
    const originalVersion = identityVersion.value;
    const controller = new AbortController();
    const abort = () => controller.abort();
    let stopWatching: WatchStopHandle | undefined;
    const assertCurrent = () => {
      let current = false;
      try {
        current = owner?.isCurrent ? owner.isCurrent() === true : true;
      } catch {
        // A failing owner check cannot authorize dispatch or accept a result.
      }
      if (
        !current || controller.signal.aborted || owner?.signal?.aborted ||
        identityVersion.value !== originalVersion || this.getOrgId() !== orgId
      ) {
        abort();
        throw new CanceledError('Task mutation owner is no longer current');
      }
    };

    // Keep this branch's original adapter and retry policy. The per-request
    // wrapper checks AFTER all asynchronous request interceptors, on every
    // attempt, immediately before entering the actual transport.
    const originalAdapter = this.client.defaults.adapter;
    const adapter: AxiosAdapter = config => {
      assertCurrent();
      // Axios 1.13.6 accepts config at runtime but omits it in index.d.ts.
      return (axios.getAdapter as (
        adapters: Parameters<typeof axios.getAdapter>[0],
        requestConfig: Parameters<AxiosAdapter>[0],
      ) => AxiosAdapter)(originalAdapter, config)(config);
    };
    try {
      assertCurrent();
      stopWatching = watch(identityVersion, abort, { flush: 'sync' });
      owner?.signal?.addEventListener('abort', abort);
      assertCurrent();
      const result = await super.delete(path, payload, { signal: controller.signal, adapter });
      assertCurrent();
      return result;
    } catch (error) {
      // ApiClient can wrap cancellation. Only normalize when this particular
      // scope is obsolete; current-owner HTTP errors still propagate unchanged.
      assertCurrent();
      throw error;
    } finally {
      stopWatching?.();
      owner?.signal?.removeEventListener('abort', abort);
    }
  }
  public async updateTask(id: string, data: dynamicObj): Promise<any> {
    const api_data: any = {};
    for (const [key, value] of Object.entries(data)) {
      api_data[key] = String(value);
    }

    return super.patch(api.api_task + '/by-id/' + id, api_data);
  }
  public async bulkUpdateStatusTasks(
    task_ids: dynamicObj,
    status: string,
  ): Promise<any> {
    const form = new FormData();
    form.append('task_ids', task_ids.join(','));
    form.append('status', status);
    return super.patch(api.api_task + '/status', form);
  }

  public async editTask(id: string, data: dynamicObj): Promise<any> {
    const api_data: any = {};
    for (const [key, value] of Object.entries(data)) {
      if (isUndefinedOrNull(value)) {
        continue;
      }
      api_data[key] = String(value);
      api_data['cache'] = false;
    }
    return super.put(api.api_task + '/by-id/' + id, api_data);
  }
}
