import { isUserAdmin } from 'src/utils/UserDetails';

/**
 * CORE-6104 — may the signed-in user change ORGANISATION preferences?
 *
 * Organisation preferences change DocBits for everybody in the organisation
 * and only organisation admins may change them (the API answers 403
 * ORG_ADMIN_REQUIRED otherwise). User preferences are the user's own and
 * stay writable by everybody. This mirrors the server rule so the UI never
 * offers a change the server will refuse.
 */
export function canWriteOrgPreferences(): boolean {
  return isUserAdmin();
}
