// Custom document validation rules (per doc-type).
// Distinct from the E-Invoice/XRechnung rules catalog handled by
// ValidationRulesApiService — these are the org-configurable
// applies_when / assertion / severity rules.
//
// GET /validation-rules?doc_type=INVOICE

import AbstractApiService from 'src/services/abstractApiService';
import { api } from 'pages/APIs';

export type CustomRuleSeverity = 'error' | 'warning' | 'info';

export type CustomRuleScope = 'header' | 'line' | 'table';

/** A single condition/assertion node. Kept loose because the backend
 *  emits several assertion shapes (pattern / range / arithmetic /
 *  field_comparison / allowed_values) and nested applies_when trees. */
export interface CustomRuleCondition {
  op?: string;
  field?: string;
  value?: unknown;
  case_insensitive?: boolean;
  not?: CustomRuleCondition;
  [key: string]: unknown;
}

export interface CustomRuleAppliesWhen {
  all?: CustomRuleCondition[];
  any?: CustomRuleCondition[];
  [key: string]: unknown;
}

export interface CustomValidationRule {
  id: string;
  doc_type: string;
  scope: CustomRuleScope;
  rule_key: string;
  display_name: string;
  description: string;
  target_field: string;
  // The document table a line/whole-table rule targets (null for header rules).
  table_name: string | null;
  applies_when: CustomRuleAppliesWhen;
  assertion: Record<string, unknown>;
  error_code: string;
  error_message: string;
  severity: CustomRuleSeverity;
  priority: number;
  is_active: boolean;
  // When true, each evaluation of this rule is logged (audit/debug trail).
  log_execution: boolean;
  source: string; // 'system_default' | 'custom' | …
  // Audit trail. `*_by` carry the actor's id (null for system-seeded
  // rules); `*_by_name` carry the resolved display name for the table.
  created_by: string | null;
  created_by_name: string | null;
  created_on: string | null;
  last_modified_by: string | null;
  last_modified_by_name: string | null;
  last_modified_on: string | null;
}

/** Body for POST /validation-rules (create). */
export interface CreateValidationRulePayload {
  doc_type: string;
  scope: CustomRuleScope;
  rule_key: string;
  display_name: string;
  description: string;
  target_field: string;
  // Omitted for header rules; carries the table for line/whole-table rules.
  table_name?: string | null;
  // Omitted entirely when the rule has no conditions — an empty match
  // ({ all: [] }) is not sent; its absence means "applies unconditionally".
  applies_when?: CustomRuleAppliesWhen;
  assertion: Record<string, unknown>;
  error_code: string;
  error_message: string;
  severity: CustomRuleSeverity;
  priority: number;
  is_active: boolean;
  log_execution: boolean;
}

/** Body for PUT /validation-rules/{id} (update).
 *  doc_type / scope / rule_key / source are immutable and omitted. */
export type UpdateValidationRulePayload = Omit<
  CreateValidationRulePayload,
  'doc_type' | 'scope' | 'rule_key'
>;

/** Body for POST /validation-rules/{id}/clone. Only the new rule's identity
 *  is sent — the backend copies scope / assertion / conditions / severity …
 *  from the source rule. */
export interface CloneValidationRulePayload {
  rule_key: string;
  display_name: string;
}

/** Body for POST /validation-rules/test — dry-run a rule against a document.
 *  The API requires EXACTLY ONE of `rule` (an unsaved draft) or `rule_id` (a
 *  saved rule). `document_id` / `doc_data` are optional targets. */
interface TestValidationRuleBase {
  document_id?: string;
  doc_data?: Record<string, unknown>;
}
export type TestValidationRulePayload = TestValidationRuleBase &
  (
    | { rule: CreateValidationRulePayload; rule_id?: never }
    | { rule_id: string; rule?: never }
  );

/** Per-row outcome returned for line-scoped rules — one entry per table row. */
export interface TestValidationRuleRowResult {
  row_index: number;
  scope_matched: boolean | null;
  passed: boolean | null;
  message: string | null;
}

/** Response of POST /validation-rules/test. For header/table scope the
 *  top-level `scope_matched` / `passed` / `message` describe the single
 *  evaluation; for line scope those are null and `rows` carries the
 *  per-row outcomes instead. */
export interface TestValidationRuleResult {
  rule_key: string;
  scope: CustomRuleScope;
  severity: CustomRuleSeverity;
  error_code: string;
  scope_matched: boolean | null;
  passed: boolean | null;
  message: string | null;
  expected: unknown;
  actual: unknown;
  rows: TestValidationRuleRowResult[] | null;
}

export default class CustomValidationRulesApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  // The org is passed via the x-org-id header on every request, so these
  // endpoints must NOT get org_id injected into the body or query string —
  // hence the *WithoutOrgId variants throughout.

  /** List the validation rules configured for a doc type. */
  public async list(docType: string): Promise<CustomValidationRule[]> {
    const url = `${api.custom_validation_rules}?doc_type=${encodeURIComponent(docType)}`;
    return super.getWithoutOrgId(url);
  }

  /** Fetch a single rule by id. GET /validation-rules/{id} */
  public async getById(ruleId: string): Promise<CustomValidationRule> {
    const url = `${api.custom_validation_rules}/${encodeURIComponent(ruleId)}`;
    return super.getWithoutOrgId(url);
  }

  /** Activate/deactivate a rule.
   *  PATCH /validation-rules/{id}/toggle  { is_active } */
  public async setActive(
    ruleId: string,
    isActive: boolean,
  ): Promise<CustomValidationRule> {
    const url = `${api.custom_validation_rules}/${encodeURIComponent(ruleId)}/toggle`;
    return super.patch(url, { is_active: isActive }, { skipOrgId: true });
  }

  /** Create a new rule. POST /validation-rules */
  public async create(
    payload: CreateValidationRulePayload,
  ): Promise<CustomValidationRule> {
    return super.postWithoutOrgId(api.custom_validation_rules, { ...payload });
  }

  /** Update an existing rule. PUT /validation-rules/{id} */
  public async update(
    ruleId: string,
    payload: UpdateValidationRulePayload,
  ): Promise<CustomValidationRule> {
    const url = `${api.custom_validation_rules}/${encodeURIComponent(ruleId)}`;
    return super.put(url, { ...payload }, { skipOrgId: true });
  }

  /** Fork a system-default rule into an editable org copy (same rule_key, new
   *  id). The override shadows the default until it is deleted (reset).
   *  POST /validation-rules/{id}/customize */
  public async customize(ruleId: string): Promise<CustomValidationRule> {
    const url = `${api.custom_validation_rules}/${encodeURIComponent(ruleId)}/customize`;
    return super.postWithoutOrgId(url, {});
  }

  /** Copy a rule into a new custom rule under a new key/name. The backend
   *  duplicates the rest of the definition, so only the identity is sent.
   *  POST /validation-rules/{id}/clone */
  public async clone(
    ruleId: string,
    payload: CloneValidationRulePayload,
  ): Promise<CustomValidationRule> {
    const url = `${api.custom_validation_rules}/${encodeURIComponent(ruleId)}/clone`;
    return super.postWithoutOrgId(url, { ...payload });
  }

  /** Delete a rule. DELETE /validation-rules/{id} */
  public async deleteValidationRule(ruleId: string): Promise<void> {
    const url = `${api.custom_validation_rules}/${encodeURIComponent(ruleId)}`;
    return super.deleteWithoutOrgId<void>(url);
  }

  /** Dry-run a draft rule against a document. POST /validation-rules/test */
  public async test<TResponse = unknown>(
    payload: TestValidationRulePayload,
  ): Promise<TResponse> {
    return super.postWithoutOrgId<TResponse>(api.custom_validation_rules_test, { ...payload });
  }
}
