// Shared envelope + primitives
// ============================================================================

/** Population block: makes the denominator of every metric explicit. */
export interface TouchlessConsultingAction {
  id: string;
  supplier_key: string;
  issue_signature: string;
  doc_type: string | null;
  scope_key: string;
  owner: string;
  next_step: string;
  due_date: string;
  status: 'open' | 'in_progress' | 'blocked' | 'measuring' | 'done';
  notes: string;
  success_criterion: string;
  version: number;
  audit: { by: string; at: string; values: Record<string, unknown> }[];
}
export type TouchlessActionDraft = Pick<
  TouchlessConsultingAction,
  'owner' | 'next_step' | 'due_date' | 'status' | 'notes' | 'success_criterion'
>;

export interface MetricPopulation {
  total: number;
  eligible: number;
  excluded: {
    count: number;
    by_reason: Record<string, number>;
  };
}

export interface MetricPeriod {
  /** The API writes `start_date` / `end_date` (`router._period`); the bare
   * names are kept for older readers. */
  start?: string;
  end?: string;
  start_date?: string;
  end_date?: string;
  period?: string;
  interval?: string;
}

/**
 * Envelope present on EVERY Automation Intelligence response.
 * `data_as_of` makes staleness explicit (no caching layer in v1),
 * `metric_contract_version` pins the bucket semantics.
 */
export interface MetricEnvelope {
  data_as_of: string;
  metric_contract_version: string;
  population: MetricPopulation;
  scope?: Record<string, unknown>;
  period?: MetricPeriod;
  trace_id?: string;
}

/** Canonical KPI buckets. Rendered raw if the backend adds new values. */
export type TouchlessBucketKey =
  | 'PURE_TOUCHLESS'
  | 'AP_TOUCHLESS'
  | 'AP_ASSISTED'
  | 'PROCESS_EXCEPTION'
  | 'IN_PROGRESS'
  | 'NOT_ELIGIBLE';

export interface TouchlessBucketValue {
  count: number;
  /**
   * Share of the rate denominator, or null when the bucket has none.
   * IN_PROGRESS and NOT_ELIGIBLE are not in that denominator, so they are
   * ALWAYS null. Typing this as `number` had TypeScript vouching for a
   * contract the runtime data never honoured.
   */
  pct: number | null;
}

export type TouchlessBuckets = Record<
  TouchlessBucketKey | string,
  TouchlessBucketValue
>;

/** Confidence of a diagnosis. Unknown values are rendered raw. */
/**
 * The DISPLAY band, derived from the API's 0-1 score by
 * `confidenceBand()` in src/utils/touchless-format.ts. The API itself sends a
 * number — this type is for what the chip shows, never for what arrives.
 */
export type TouchlessConfidence = 'high' | 'medium' | 'low';

/** Stage status inside a document trace. */
export type TouchlessStageStatus =
  | 'passed'
  | 'blocked'
  | 'failed'
  | 'skipped'
  | 'not_applicable';

