// ============================================================================
// POST /issues/{signature}/advice/generate
// ============================================================================

/**
 * Languages the advisor accepts. Anything else is IGNORED by the backend
 * (it falls back to the org's `PREFERRED_LANGUAGE`), so sending `de-DE` is not
 * an error — it just quietly produces English. Normalising here means the
 * caller can hand over a raw UI locale and still get German.
 */
export const TOUCHLESS_ADVICE_LANGUAGES = [
  'en',
  'en-us',
  'de',
  'es',
  'es-es',
  'fr',
  'nl',
  'it',
  'zh',
] as const;

/**
 * What one generate request actually did.
 *
 * `ready`/`running`/`disabled`/`unavailable` are the backend's four documented
 * outcomes; `forbidden` and `not_found` are the two refusals, kept as outcomes
 * rather than exceptions because the card has to SAY which one happened and
 * keep its deterministic content on screen either way.
 */
export type TouchlessAdviceGenerateOutcome =
  | 'ready'
  | 'running'
  | 'disabled'
  | 'unavailable'
  | 'forbidden'
  | 'not_found';

/**
 * What the bulk button may report (DOCB-14285).
 *
 * `empty` is its own outcome, not a zero-count `running`: nothing was started,
 * so the UI must not enter a "waiting for results" state that never resolves.
 */
export type TouchlessBulkAdviceOutcome =
  | 'running'
  | 'empty'
  | 'disabled'
  | 'unavailable'
  | 'forbidden';

export interface TouchlessBulkAdviceResult {
  outcome: TouchlessBulkAdviceOutcome;
  httpStatus: number;
  /** Analyses the dispatched run will perform. 0 for every non-`running`. */
  dispatched: number;
  /**
   * The clusters the run covers, so the caller can WATCH it (DOCB-14285).
   *
   * Empty for every non-`running` outcome, and empty against a backend that
   * predates the field — which is why progress is offered only when this list
   * is non-empty rather than whenever `dispatched > 0`. An older API then
   * degrades to exactly the toast-only behaviour it had before, instead of
   * leaving an indicator at 0/8 that nothing can ever advance.
   */
  signatures: string[];
  /**
   * When the run started on the SERVER's clock (`dispatched_at`), and the
   * reference every read-back is measured against (DOCB-14285).
   *
   * Null for every non-`running` outcome and against a backend that predates
   * the field; the progress aggregation then falls back to the advice status
   * alone.
   */
  dispatchedAt: string | null;
  /**
   * How many of the dispatched signatures already carry a reusable analysis
   * (DOCB-14312), and when anything was last analysed.
   *
   * A pre-flight EXPECTATION, not a result: it describes the stored rows as
   * the worker will find them. The proven answer arrives afterwards from
   * `getBulkAdviceStatus`, whose `cached` compares each row's `generated_at`
   * against this dispatch. Null against a backend without the fields — never
   * 0, which would be a claim this client cannot make.
   */
  alreadyAnalyzedCount: number | null;
  newCount: number | null;
  lastAnalyzedAt: string | null;
  /** The dispatched signatures expected to be served from the cache. */
  cachedSignatures: string[];
  /**
   * The server's handle for this run (DOCB-14327).
   *
   * Handed back to `getBulkAdviceStatus`, which then answers the run in the
   * scope it was DISPATCHED in — the signatures, window and language the
   * worker was actually given — instead of rebuilding one from the polling
   * request's own context. Null against a backend that predates the field, or
   * when the server could not record the run; the poll then sends the
   * signatures itself exactly as before.
   */
  runId: string | null;
  message: string | null;
}

/**
 * Whether these reads are narrowed to a sub-organisation, and its name
 * (DOCB-14313).
 *
 * `scoped` is the SAME decision `buildSubOrgScopeParams` makes for the query
 * string — including its two deliberate refusals (no organisation id yet; the
 * "sub-org" IS the organisation), both of which mean org-wide.
 */
export interface TouchlessSubOrgScope {
  scoped: boolean;
  /** Display name, or '' when there is no sub-organisation to name. */
  name: string;
}

/**
 * One dispatched signature's progress, as the bulk-status route reports it
 * (DOCB-14315).
 */
export interface TouchlessBulkStatusEntry {
  signature: string;
  /** `pending` | `running` | `done` | `error`, verbatim from the backend. */
  status: string;
  /**
   * True when this run touched the row but recomputed nothing — the advisor
   * handed its claim back because the cache was still fresh.
   */
  cached: boolean;
  updatedAt: string | null;
  generatedAt: string | null;
  lastError: string | null;
}

/**
 * The whole bulk run in one answer (DOCB-14315).
 *
 * `supported` is the one field the backend does not send: it is this client's
 * record of whether the route answered at all. The API ships before the Web
 * does, but a rollback must not freeze the indicator at 0/N with no way to
 * advance — a `false` here sends the store back to the per-cluster read it
 * used before, which is slow but correct.
 */
export interface TouchlessBulkStatusResponse {
  supported: boolean;
  statuses: TouchlessBulkStatusEntry[];
  total: number;
  pendingCount: number;
  runningCount: number;
  doneCount: number;
  errorCount: number;
  cachedCount: number;
  complete: boolean;
  /**
   * The run this answer describes (DOCB-14327), echoed by the backend.
   *
   * Null when no `run_id` was sent, and — importantly — also when one was sent
   * that the server no longer knows (an expired record, a different org). The
   * caller can then tell "the server answered my run" from "this is my own
   * query again" without a second request.
   */
  runId: string | null;
}

/**
 * The last bulk run started from this view, plus where it has got to
 * (DOCB-14328).
 *
 * `status` is `ready` when there is a run to restore and `none` for every
 * kind of absence — no run, a run from another view, an expired record, a
 * backend that predates the route. A panel that has just mounted must never
 * fail to mount because there was nothing to put back.
 */
export interface TouchlessLatestBulkRun extends TouchlessBulkStatusResponse {
  status: string;
  signatures: string[];
  dispatchedAt: string | null;
}

/**
 * The threshold to state when the backend did not state one (DOCB-14335).
 *
 * `min_affected` is a backend constant (`TOUCHLESS_ADVISOR_MIN_AFFECTED`, 3)
 * and zero is not one of its values — so a 0 here can only mean "not told",
 * and it is a printed number: the panel renders "no cluster affects at least
 * {min} documents". A failed preview used to put "at least 0 documents" on
 * screen as though it were a measurement.
 */
export const TOUCHLESS_BULK_MIN_AFFECTED_DEFAULT = 3;

/** The reasons an advisor can be off that this client knows how to say. */
export type TouchlessAdvisorDisabledReason = 'no_api_key' | 'kill_switch';

const TOUCHLESS_ADVISOR_DISABLED_REASONS: TouchlessAdvisorDisabledReason[] = [
  'no_api_key',
  'kill_switch',
];

export interface TouchlessBulkAdvicePreview {
  /** `ready` | `disabled` | `unavailable`, verbatim from the backend. */
  status: string;
  /** How many clusters a click would analyse, already capped by the budget. */
  eligibleCount: number;
  /** Max analyses per invocation, so the UI can explain the cap. */
  budget: number;
  /** Minimum affected documents a cluster needs, so a 0 can be explained. */
  minAffected: number;
  /**
   * Whether the environment can run an AI analysis at all (DOCB-14335).
   *
   * Defaults to `true` against a backend that predates the field: the button
   * behaved as though the advisor were available before this existed, and a
   * client that has not been told must not start claiming otherwise.
   */
  advisorEnabled: boolean;
  /**
   * Why not, when the backend named a reason it knows how to render — a
   * missing API key or the operator kill switch — and `null` for every other
   * case: no reason sent, an unknown future reason code, or an advisor that
   * is running. A code this client cannot translate must never be printed at
   * a user.
   */
  advisorDisabledReason: TouchlessAdvisorDisabledReason | null;
  /**
   * How many of those clusters already carry an analysis the run would REUSE
   * rather than recompute (DOCB-14312).
   *
   * `null` against a backend that predates the field — not `0`, which would
   * be a claim ("nothing has been analysed") this client cannot make. The
   * panel renders the breakdown only when it really knows.
   */
  alreadyAnalyzedCount: number | null;
  /** The remainder, stated by the backend rather than subtracted here. */
  newCount: number | null;
  /** When anything in this selection was last analysed, ISO, or null. */
  lastAnalyzedAt: string | null;
  /**
   * How the selection splits into work the customer can do and work only the
   * supplier can (DOCB-14318).
   *
   * `null` against a backend that predates the fields — not `0`, which would
   * be a claim ("nothing is fixable") this client cannot make. Counted by the
   * backend over the SAME selection `eligibleCount` comes from, so the three
   * numbers always add up.
   */
  fixableCount: number | null;
  supplierOnlyCount: number | null;
}

/** A non-negative integer from an untyped JSON field, or 0. */
function toCount(value: unknown): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) return 0;
  return Math.floor(parsed);
}

/**
 * A non-negative integer, or null when the backend did not send one.
 *
 * Distinct from `toCount` on purpose (DOCB-14312): a missing
 * `already_analyzed_count` means "this backend cannot tell me", and folding
 * that to 0 would put "0 already analysed" on screen as though it were a
 * measurement.
 */
function toOptionalCount(value: unknown): number | null {
  if (value === null || value === undefined) return null;
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) return null;
  return Math.floor(parsed);
}

/** A non-negative integer, or `fallback` when the backend did not send one. */
function toCountOr(value: unknown, fallback: number): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
  return Math.floor(parsed);
}

/** The advisor block of a preview, as much of it as this client understands. */
function advisorStateFrom(value: unknown): {
  advisorEnabled: boolean;
  advisorDisabledReason: TouchlessAdvisorDisabledReason | null;
} {
  const advisor = (value ?? {}) as Record<string, unknown>;
  const enabled = typeof advisor.enabled === 'boolean' ? advisor.enabled : true;
  const reason = advisor.disabled_reason;
  const known = TOUCHLESS_ADVISOR_DISABLED_REASONS.find((r) => r === reason);
  return {
    advisorEnabled: enabled,
    advisorDisabledReason: enabled ? null : (known ?? null),
  };
}

/** An ISO timestamp the backend sent, or null. */
function toOptionalTimestamp(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value : null;
}

/** The signatures a `signature_states` array flags as cached. */
function cachedSignaturesFrom(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  const out: string[] = [];
  for (const entry of value) {
    if (!entry || typeof entry !== 'object') continue;
    const row = entry as Record<string, unknown>;
    if (row.cached !== true) continue;
    if (typeof row.issue_signature === 'string' && row.issue_signature.trim()) {
      out.push(row.issue_signature);
    }
  }
  return out;
}

/** A zero-row bulk status. `supported` says whether the route answered. */
/**
 * One `bulk-status`-shaped body, read defensively (DOCB-14328).
 *
 * Extracted because `bulk-runs/latest` answers with exactly the same block —
 * it runs the same server-side projection — and two hand-kept readers of one
 * payload would be one field away from the poll and the restore describing
 * the same run differently.
 */
function parseBulkStatusPayload(
  data: Record<string, unknown>,
): TouchlessBulkStatusResponse {
  const rawStatuses = Array.isArray(data.statuses) ? data.statuses : [];
  const statuses: TouchlessBulkStatusEntry[] = [];
  for (const entry of rawStatuses) {
    if (!entry || typeof entry !== 'object') continue;
    const row = entry as Record<string, unknown>;
    const signature =
      typeof row.issue_signature === 'string' ? row.issue_signature : '';
    if (!signature) continue;
    statuses.push({
      signature,
      status: typeof row.status === 'string' ? row.status : '',
      cached: row.cached === true,
      updatedAt: typeof row.updated_at === 'string' ? row.updated_at : null,
      generatedAt:
        typeof row.generated_at === 'string' ? row.generated_at : null,
      lastError: typeof row.last_error === 'string' ? row.last_error : null,
    });
  }

  return {
    supported: true,
    statuses,
    total: toCount(data.total),
    pendingCount: toCount(data.pending_count),
    runningCount: toCount(data.running_count),
    doneCount: toCount(data.done_count),
    errorCount: toCount(data.error_count),
    cachedCount: toCount(data.cached_count),
    complete: data.complete === true,
    runId:
      typeof data.run_id === 'string' && data.run_id.trim()
        ? data.run_id.trim()
        : null,
  };
}

/** "There is nothing to restore" — the answer for every kind of absence. */
function emptyLatestBulkRun(): TouchlessLatestBulkRun {
  return {
    ...emptyBulkStatus(true),
    status: 'none',
    signatures: [],
    dispatchedAt: null,
  };
}

function emptyBulkStatus(supported: boolean): TouchlessBulkStatusResponse {
  return {
    supported,
    statuses: [],
    total: 0,
    pendingCount: 0,
    runningCount: 0,
    doneCount: 0,
    errorCount: 0,
    cachedCount: 0,
    complete: false,
    runId: null,
  };
}

export interface TouchlessAdviceGenerateResult {
  outcome: TouchlessAdviceGenerateOutcome;
  /** The raw HTTP status, so a caller can log what really happened. */
  httpStatus: number;
  issueSignature: string;
  /** Only on `ready`: the cached advice the server served without spending. */
  advice: TouchlessAdvice | null;
  /** Server wording for a refusal or a failed dispatch. */
  message: string | null;
}

export interface TouchlessAdviceGenerateParams {
  /** Cluster window in days — must match the window the card was read with. */
  window?: number;
  /** Advice language; ignored by the backend unless it is a supported tag. */
  lang?: string | null;
}

/** `de-DE` → `de`, `EN` → `en`, anything unsupported → undefined. */
/** A finite number, or null — never a 0 standing in for "not sent". */
function toOptionalRate(value: unknown): number | null {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

/**
 * The server's own wording for a refusal.
 *
 * doc2-api sends `detail` for an `HTTPException` and `message` through its
 * Starlette handler; both are read because both reach this client, and the
 * sentence is the only part of a 409 a reader can act on.
 */
function messageFrom(data: Record<string, unknown>): string | null {
  for (const key of ['message', 'detail'] as const) {
    const value = data[key];
    if (typeof value === 'string' && value.trim()) return value;
  }
  return null;
}

/**
 * A refusal's stable `error_code`, when the server sent one and it is one of
 * this panel's (CORE-6368). The API names codes in upper case
 * (`TOUCHLESS_PROPOSAL_PREVIEW_INVALID`); the lower-cased code is the
 * translation key. The sentence next to it is a developer instruction ("POST
 * /change-proposals/{id}/preview first") that must not reach a customer, so the
 * panel prints the translated message instead. Any other code is ignored, and
 * the sentence stays the clue it was.
 */
function codeFrom(data: Record<string, unknown>): string | null {
  const value = data.error_code;
  return typeof value === 'string' && value.startsWith('TOUCHLESS_PROPOSAL_')
    ? value.toLowerCase()
    : null;
}

/**
 * HTTP status → what the reader is told. Each of these needs different words:
 * "you are not an org admin", "this cluster is gone", "somebody changed the
 * setting while you were reading", "you have used this hour's ten changes".
 */
const APPLY_REFUSALS: Record<number, TouchlessApplyOutcome> = {
  403: 'forbidden',
  404: 'not_found',
  409: 'conflict',
  429: 'rate_limited',
};

const REVERT_REFUSALS: Record<number, TouchlessRevertOutcome> = {
  403: 'forbidden',
  404: 'not_found',
  409: 'conflict',
};

/** A refused dry run, with every number at its "nothing known" value. */
function emptyPreview(
  outcome: TouchlessPreviewOutcome,
): TouchlessChangePreviewResult {
  return {
    outcome,
    httpStatus: 0,
    previewToken: null,
    expiresAt: null,
    wouldBeTouchless: { count: 0, docIds: [] },
    stillBlocked: [],
    sideEffects: [],
    sampledDocCount: 0,
    diff: { currentValue: null, proposedValue: null },
    message: null,
  };
}

export function normalizeAdviceLanguage(
  value: string | null | undefined,
): string | undefined {
  if (typeof value !== 'string') return undefined;
  // `_` and `-` are the same separator to a reader; the allow-list uses `-`.
  const tag = value.trim().toLowerCase().replace(/_/g, '-');
  if (!tag) return undefined;
  const supported = TOUCHLESS_ADVICE_LANGUAGES as readonly string[];
  if (supported.includes(tag)) return tag;
  const base = tag.split('-')[0];
  return supported.includes(base) ? base : undefined;
}

