  /**
   * Run the advisor over ONE supplier's clusters — DOCB-14337.
   *
   * The supplier diagnosis page had no action at all: a reader who arrived
   * from a tile and wanted this supplier's issues explained had to go back to
   * the analytics tab and press the org-wide button, which analyses whatever
   * the org's top clusters happen to be — very possibly not this supplier's.
   *
   * The backend runs the SAME selection statement the org-wide bulk button
   * runs, narrowed to this supplier and at a minimum cluster size of 1, so the
   * set this returns is the set the workers took. Progress is then read
   * through the existing per-cluster advice polling — no second mechanism.
   *
   * Never throws for a refusal the page can render: 200 with `empty` /
   * `disabled` and 403 all come back as an outcome, because a reader who
   * clicked deserves a sentence, not a silent no-op.
   */
  public async generateSupplierDiagnosis(
    supplierKey: string,
    params: TouchlessAdviceGenerateParams & { docType?: string | null } = {},
  ): Promise<TouchlessSupplierDiagnosisResult> {
    const endpoint =
      `${TOUCHLESS_API_BASE}/suppliers/${encodeURIComponent(supplierKey)}` +
      '/diagnosis/generate';

    const body: Record<string, unknown> = {};
    if (params.docType) body.doc_type = params.docType;
    if (typeof params.window === 'number' && Number.isFinite(params.window)) {
      body.window = params.window;
    }
    const lang = normalizeAdviceLanguage(params.lang);
    if (lang) body.lang = lang;
    // The header the reader started the run from (DOCB-14327). It does not
    // narrow anything — the run is already narrowed to one supplier — it only
    // files the run so `bulk-runs/latest` restores it under that header.
    const subOrgId = await this.resolveSubOrgId();
    if (subOrgId) body.sub_org_id = subOrgId;

    const options: Record<string, unknown> = {};
    await this.addTokenToOptions(options, {});
    (options.headers as Record<string, string>)['Content-Type'] =
      'application/json';
    options.validateStatus = (status: number) =>
      status === 200 || status === 202 || status === 403;

    let response;
    try {
      response = await this.client.post(endpoint, body, options);
    } catch (error) {
      await this.handleError(error);
      throw error;
    }

    const status = Number(response?.status);
    const data = (response?.data ?? {}) as Record<string, unknown>;
    const message = typeof data.message === 'string' ? data.message : null;

    if (status === 403) {
      return {
        outcome: 'forbidden',
        dispatched: 0,
        signatures: [],
        runId: null,
        dispatchedAt: null,
        message,
      };
    }

    const signatures = normalizeBulkSignatures(data.signatures);
    return {
      // The server's own word for what happened. `empty` and `disabled` are
      // 200s and must NOT read as a started run, or the page waits for results
      // that are never coming.
      outcome: typeof data.status === 'string' ? data.status : 'unavailable',
      dispatched:
        typeof data.dispatched === 'number' && Number.isFinite(data.dispatched)
          ? data.dispatched
          : signatures.length,
      signatures,
      runId: typeof data.run_id === 'string' ? data.run_id : null,
      dispatchedAt:
        typeof data.dispatched_at === 'string' && data.dispatched_at.trim()
          ? data.dispatched_at
          : null,
      message,
    };
  }

