// Aliases mapped to the canonical column name. Applied ONLY at the
// backend-serialisation edge (`canonicaliseForBackend`), never in the
// parsed predicate list or the chip editor. Keeps `imported_on=today()`
// visible exactly as the user typed it while the HTTP request still
// carries `created_on=2026-04-22`.
export const FIELD_ALIASES: Record<string, string> = {
  imported_on: 'created_on',
  updated: 'last_modified_on',
  updated_on: 'last_modified_on',
  // Procurement vocabulary — the underlying ClickHouse dashboard
  // column is `supplier_name` (constants/clickhouse.py). Frontend
  // accepts the procurement term `vendor_name` for both raw_query
  // predicates and group-by directives, and rewrites it to the
  // canonical column name BEFORE shipping to the backend so the
  // GROUP BY / WHERE clause references a real column.
  vendor_name: 'supplier_name',
  // Bug-2026-05-29: the backend `/document_process/search/fields` API
  // surfaces `file_name` as a separate OpenSearch custom-field entry
  // alongside the standard `filename` column — both labelled
  // "Dokumentname" via _CUSTOM_FIELD_LABEL_KEY_OVERRIDES. Picking the
  // fulltext-section variant in the dropdown produces a chip with
  // `field='file_name'`, but the actual OpenSearch index path is
  // `metadata.extracted_fields.filename` (NOT `file_name`), so the
  // query returns zero results. Rewrite at the wire boundary so the
  // chip keeps `category='fulltext'` (→ `is_fulltext=true` routing
  // stays correct) while the field name lands on the indexed path.
  // Backend follow-up: add `('file_name', 'filename')` to
  // `_AST_FIELD_ALIAS_GROUPS` in
  // fulltextsearch/routers/opensearch/executer.py so other clients
  // (DocFlow, OpenAPI consumers) get the alias too.
  file_name: 'filename',
};

// Field metadata used by the UI autocomplete. Three categories drive
// the colour in the search input:
//   - standard: blue  (fast Postgres path — always available)
//   - fulltext: orange (needs OpenSearch — range or extracted-only)
//   - vector:   purple (needs Vector module — semantic prefix)
//   - ocr:      green (needs Fulltext module — OCR/table content prefix)
// The `ops` list is only for the tooltip / hint — the parser accepts
// everything and the backend does the real validation.
export type ValueType = 'numeric' | 'date' | 'enum' | 'uuid' | 'string';

export interface FieldMeta {
  name: string;
  // 'standard' = direct documents-table column (fast PG path)
  // 'extended' = projected from document_extracted_data EAV onto a typed
  //              ClickHouse column via SYNC_COLUMNS — filterable as SQL
  //              column without OpenSearch round-trip.
  // 'fulltext' = needs OpenSearch (custom doc-type fields, range ops on
  //              non-projected fields).
  // 'vector'   = semantic-similarity prefix (vector:). kNN over document
  //              embeddings — pure cosine-similarity match.
  // 'ai'       = LLM-based natural-language query parser (ai:). The
  //              backend's Ollama service rewrites the phrase into a
  //              structured query. NOT the same as vector kNN; routed
  //              through fulltextsearch's ai_query_parser, not the
  //              vector index.
  // 'ocr'      = explicit OCR/table/text-companion prefix (ocr:).
  category: 'standard' | 'extended' | 'fulltext' | 'vector' | 'ocr' | 'ai';
  ops: readonly string[]; // typical operators for this field
  // Drives smart-commit rules in QuickSearchBox — numeric/date/enum/uuid
  // values commit on space; string values wait for Enter/Tab so multi-
  // word strings aren't prematurely cut.
  valueType: ValueType;
  // Human-friendly label shown in the autocomplete dropdown. Overrides
  // the automatic Title-Case of `name`. Use this whenever the raw
  // identifier (invoice_id, ap_assignment_code) misleads the user
  // about what the field means (it's Invoice Number, not Invoice Id).
  // When omitted, FieldAutocomplete falls back to prettyFieldName(name).
  displayName?: string;
  // English description used as fallback / for parser tests / documentation.
  description: string;
  // i18n key resolved in the Vue layer via $t(). Keeping the English
  // fallback here lets non-Vue consumers (unit tests, tooling) read the
  // catalog without pulling in Tolgee.
  descriptionKey: string;
  // Short i18n key used as the chip label — one or two words, never a
  // sentence. The dropdown keeps descriptionKey (longer, descriptive);
  // chips use labelKey so rows stay compact. Falls back to descriptionKey
  // when omitted.
  labelKey?: string;
  example: string;
  // When true, the operator picker offers "is not empty" / "is empty"
  // presets that emit the complete `field!=""` / `field=""` predicate in
  // one click. Default false. Useful for fields that may be unset (most
  // extracted fulltext fields, plus a handful of standard columns).
  supportsPresence?: boolean;
  docTypes?: string[];
}

// MUTABLE on purpose: hydrated from the `extended_field_names` payload
// of `GET /document/search/fields` so custom doc-type fields tagged
// dynamically per org get the correct routing class. Empty fallback
// keeps the function pure during unit tests / pre-hydration boot —
// custom fields default to 'fulltext' until the catalog hydrator
// populates this set.
let _EXTENDED_FIELD_NAMES: ReadonlySet<string> = new Set();
let _CUSTOM_FIELD_NAMES: ReadonlySet<string> = new Set();
// Subset of `_CUSTOM_FIELD_NAMES` whose value is free-form text (custom
// doc-type fields that are NOT numeric/date). Used by
// `isMultiTokenStringField` so a pasted multi-word value for a custom
// string field is auto-quoted like `supplier_name` (OBO-46 / Codex review).
let _CUSTOM_STRING_FIELD_NAMES: ReadonlySet<string> = new Set();
// Subset of `_CUSTOM_FIELD_NAMES` whose value is a DATE (custom doc-type
// fields tagged `field_type === 'DATE'`). These never reach the static
// FIELD_CATALOG, so `isDateValueField` consults this set to let the
// dashboard format them with the user's date pattern (DOCB-12248).
let _CUSTOM_DATE_FIELD_NAMES: ReadonlySet<string> = new Set();

export function setExtendedFieldNames(
  names: ReadonlySet<string> | string[],
): void {
  _EXTENDED_FIELD_NAMES = names instanceof Set ? names : new Set(names);
}

export function getExtendedFieldNames(): ReadonlySet<string> {
  return _EXTENDED_FIELD_NAMES;
}

export function setCustomFieldNames(
  names: ReadonlySet<string> | string[],
): void {
  const values = Array.from(names);
  _CUSTOM_FIELD_NAMES = new Set(values.map((name) => name.toLowerCase()));
}

export function getCustomFieldNames(): ReadonlySet<string> {
  return _CUSTOM_FIELD_NAMES;
}

function isSupportedSearchField(fieldName: string): boolean {
  return (
    SUPPORTED_FIELDS.has(fieldName) ||
    _CUSTOM_FIELD_NAMES.has(fieldName) ||
    FIELD_CATALOG.some((field) => field.name === fieldName)
  );
}

// Bug-2026-05-25 #8: custom fulltext fields rendered their raw
// backend `field_name` (e.g. `file_name`) as the dropdown label
// because no `labelKey` was set on the FieldMeta.  When the backend
// field name conceptually overlaps with a standard FIELD_CATALOG
// entry, reuse that entry's `labelKey` so both panels show the same
// human label (e.g. "Document name" for both `filename` standard and
// `file_name` fulltext).  Keep this map small — it's NOT a generic
// alias system; it's a UX fix for fields that exist in both worlds.
const _CUSTOM_FIELD_LABEL_KEY_OVERRIDES: Record<string, string> = {
  // OpenSearch property `file_name` mirrors Postgres column `filename`.
  // Both surface to the user as "Document name" — see en.json key
  // `filename`.
  file_name: 'filename',
};

// DOCB-12865: backend field names that are a DERIVED COPY of a standard
// FIELD_CATALOG field — same value, second name — and must therefore not
// get a dropdown row of their own.  Unlike
// `_CUSTOM_FIELD_LABEL_KEY_OVERRIDES` above (fields that legitimately
// exist in both worlds and should share a label), these carry no extra
// information: showing both leaves the user with two rows reading
// "Invoice number" and no way to tell them apart.
//
//   invoice_number → invoice_id
//     The fulltext backend copies the extracted `invoice_id` value into a
//     business field literally named `invoice_number`
//     (`business_fields["invoice_number"] = invoice_id["value"]`,
//     fulltextsearch routers/opensearch/executer.py).  Orgs whose
//     `/document_process/search/fields` response echoes it back used to
//     get the duplicate row that DOCB-12865 reported.
//
// The derived name stays in SUPPORTED_FIELDS on purpose: raw queries,
// pasted URLs and saved filters that reference it must keep parsing as a
// predicate — only the picker row goes away.  Keep this map TINY.
const _CUSTOM_FIELD_DERIVED_DUPLICATES: Record<string, string> = {
  invoice_number: 'invoice_id',
};

export function customFieldsToFieldMetas(
  raw:
    | {
        field_name: string;
        title: string;
        doc_types: string[];
        field_type?: string;
      }[]
    | null
    | undefined,
): FieldMeta[] {
  // When the Pinia getAllUniqueFieldsWithDocTypes getter throws (e.g. during
  // store hydration), Vue caches undefined as the computed value. Callers
  // then pass that undefined here, crashing on raw.map(). Return [] so the
  // cascade (effectiveCustomFulltextFields → groups()) stays clean.
  const fields = Array.isArray(raw) ? raw : [];
  const knownNames = new Set(FIELD_CATALOG.map((f) => f.name));
  setCustomFieldNames(
    fields
      .map((field) => field?.field_name)
      .filter(
        (name): name is string => typeof name === 'string' && name.length > 0,
      ),
  );
  const metas = fields
    .filter((c) => !!c?.field_name && !!c?.title)
    .filter((c) => !knownNames.has(c.field_name))
    // DOCB-12865: hide names that only duplicate a catalog field's value
    // (and therefore its label).  Gated on the canonical field actually
    // being in the catalog — if the backend ever drops `invoice_id`, the
    // derived name is the only way to reach the value and stays visible.
    .filter((c) => {
      const canonical = _CUSTOM_FIELD_DERIVED_DUPLICATES[c.field_name];
      return !canonical || !knownNames.has(canonical);
    })
    .map((c) => {
      const fieldType = String(c.field_type ?? '').toUpperCase();
      const isNumeric = ['AMOUNT', 'NUMBER', 'CURRENCY', 'CHARGES'].includes(
        fieldType,
      );
      const isDate = fieldType === 'DATE';
      // Resolve a labelKey for fields whose backend name overlaps with
      // a standard FIELD_CATALOG entry's i18n key.  Falls through to
      // the API-provided title for anything else (the existing
      // behaviour for genuine custom doc-type fields).
      const labelKey = _CUSTOM_FIELD_LABEL_KEY_OVERRIDES[c.field_name];
      return {
        name: c.field_name,
        // Promote to 'extended' (teal) when the backend tells us this
        // field name is in SYNC_COLUMNS — it's then ClickHouse-projected
        // and SQL-filterable. Otherwise stays 'fulltext' (orange).
        category: (_EXTENDED_FIELD_NAMES.has(c.field_name)
          ? 'extended'
          : 'fulltext') as 'extended' | 'fulltext',
        ops: isNumeric
          ? ['=', '!=', '>', '<', '>=', '<=']
          : isDate
            ? ['between', '>=', '<=']
            : ['=', ':', '!='],
        valueType: isNumeric
          ? ('numeric' as const)
          : isDate
            ? ('date' as const)
            : ('string' as const),
        ...(labelKey ? { labelKey } : {}),
        displayName: c.title,
        description: c.title,
        descriptionKey: '',
        example: '',
        supportsPresence: true,
        docTypes: Array.isArray(c.doc_types) ? c.doc_types : [],
      };
    });
  // Remember which custom fields are free-form text so paste-quoting can
  // treat them like `supplier_name` (Codex review).
  _CUSTOM_STRING_FIELD_NAMES = new Set(
    metas
      .filter((m) => m.valueType === 'string')
      .map((m) => m.name.toLowerCase()),
  );
  // Remember which custom fields are dates so the dashboard formats them
  // with the user's date pattern (DOCB-12248) — these are absent from the
  // static FIELD_CATALOG that `isDateValueField` checks first.
  _CUSTOM_DATE_FIELD_NAMES = new Set(
    metas
      .filter((m) => m.valueType === 'date')
      .map((m) => m.name.toLowerCase()),
  );
  return metas;
}

