// document. Unset, the legacy switch decides.
export const table_extraction_vision_mode_setting =
  'TABLE_EXTRACTION_VISION_MODE';
export type VisionMode = 'off' | 'vision' | 'hybrid' | 'auto';
export const visionModeList: { label: string; value: VisionMode }[] = [
  { label: 'vision_mode_off', value: 'off' },
  { label: 'vision_mode_vision', value: 'vision' },
  { label: 'vision_mode_hybrid', value: 'hybrid' },
  { label: 'vision_mode_auto', value: 'auto' },
];

export function resolveVisionMode(
  stored: unknown,
  legacy: unknown,
): VisionMode {
  const mode = String(stored ?? '')
    .trim()
    .toLowerCase();
  if (visionModeList.some((m) => m.value === mode)) return mode as VisionMode;
  return legacy === true || String(legacy).toLowerCase() === 'true'
    ? 'vision'
    : 'off';
}

// The legacy switch stays true only for the images-only mode, so services
// that read only TABLE_EXTRACTION_USE_VISION keep today's behaviour.
export function legacyVisionFor(mode: VisionMode): boolean {
  return mode === 'vision';
}
