export type AiTierLabel =
  | 'Full'
  | 'Fast'
  | 'Nexus'
  | 'Nexus Flash'
  | 'Auto'
  | 'Auto Nexus';

// Resolve any stored AI_MODEL value to a UI tier label. Single source for
// every surface that renders a tier (supplier table, tooltips, selects) —
// mirrors doc2-api's resolve_ai_model(). Handles unset/placeholder values,
// fine-tune ids (ft:<base>:<org>::<id>), legacy pre-gpt-5.x ids and the
// retired Turbo tier (gpt-5.4-nano → Fast, its server-side migration target).
// CORE-6108: the tier label for an id this app KNOWS (current tier value,
// its fine-tune variant, or a legacy pre-migration id) — null for anything
// else. The settings assistant uses this so an unknown id is never guessed
// into a tier AND never shown raw; getAiTierLabel adds the size-hint guess.
export function resolveKnownAiTierLabel(
  ai_model?: string | null,
): AiTierLabel | null {
  if (!ai_model) return null;
  // Extract the base model from a fine-tune id (ft:<base>:<org>::<id>) —
  // same split as doc2-api's resolve_ai_model, so the legacy map and exact
  // matches below see a clean base id, not "<base>:<org>::<id>".
  const base = ai_model.startsWith('ft:')
    ? ai_model.split(':')[1] || ai_model
    : ai_model;
  // Exact current-tier match.
  const match = aiModelList.find((item) => item.value === base);
  if (match) return match.label as AiTierLabel;
  // Legacy stored ids (pre gpt-5.x migration) → tier. gpt-5 used to map to
  // Turbo; DOCB-13483 retired the tier and migrated its selections to Fast.
  const legacyTierMap: Partial<Record<string, AiTierLabel>> = {
    'gpt-4o': 'Full',
    'gpt-4o-mini-2024-07-18': 'Fast',
    'gpt-5': 'Fast',
    // DOCB-14759: tier models before gpt-6, until the server-side migration
    // gpt6_tier_models_260923 rewrites them.
    'gpt-5.5': 'Full',
    'gpt-5.4-mini': 'Fast',
  };
  return legacyTierMap[base] ?? null;
}

export function getAiTierLabel(ai_model?: string | null): AiTierLabel {
  // Unset rows fall back to the backend default tier
  // (Fast = gpt-6-luna, the doc2-api DEFAULT_AI_MODEL).
  const DEFAULT_TIER: AiTierLabel = 'Fast';
  if (!ai_model || ai_model === '-') return DEFAULT_TIER;
  const known = resolveKnownAiTierLabel(ai_model);
  if (known) return known;
  const base = ai_model.startsWith('ft:')
    ? ai_model.split(':')[1] || ai_model
    : ai_model;
  // Unknown / fine-tuned ids: classify by size hint so the cell is still a tier.
  const lower = base.toLowerCase();
  if (lower.includes('nano')) return 'Fast';
  if (lower.includes('mini')) return 'Fast';
  return 'Full';
}

