// CORE-6108 — the settings-assistant chat's URL allowlists. ONE allowlist per
// concern, both enforced the same way (https, exact host, no credentials, no
// port) so a chat answer can only ever link/embed what the backend contract
// actually promises (DocBits_API deep_links.py doc_url / images).
//
// Doc links: docs.docbits.com only.
export const SETTINGS_ASSISTANT_DOCS_HOST = 'docs.docbits.com';
//
// Images: docs.docbits.com itself, the GitBook per-space assets CDN behind
// it (DocBits_API PR #11742: host shape `<numeric-space-id>-files.gitbook.io`
// — confirmed live for main=578966019, de=2396827744; every other language
// branch gets its own numeric id, hence a pattern match rather than a fixed
// list), and the settings-assistant screenshot bucket (CORE-6112).
export const SETTINGS_ASSISTANT_GITBOOK_ASSET_HOST_SUFFIX = '-files.gitbook.io';
export const SETTINGS_ASSISTANT_SCREENSHOT_BUCKET_HOST =
  'cloudintegration-xrechnung.fra1.digitaloceanspaces.com';
export const SETTINGS_ASSISTANT_SCREENSHOT_PATH_PREFIX =
  '/xrechnung/settings-assistant/screens/';

/**
 * https only, exact host, no userinfo (`user:pass@host`), no explicit port —
 * the shared shape every settings-assistant URL check starts from. A bare
 * `try { new URL(...) }` already rejects `javascript:`/`data:` schemes here
 * because their `.protocol` is never `'https:'`.
 */
function isHttpsUrlWithHost(
  url: string,
  hostOk: (hostname: string) => boolean,
): boolean {
  if (typeof url !== 'string' || !url) return false;
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return false;
  }
  if (parsed.protocol !== 'https:') return false;
  if (parsed.username || parsed.password) return false;
  if (parsed.port) return false;
  return hostOk(parsed.hostname);
}

/** The settings-assistant chat's doc link / source link allowlist. */
export function isSettingsAssistantDocsUrl(url: string): boolean {
  return isHttpsUrlWithHost(
    url,
    (host) => host === SETTINGS_ASSISTANT_DOCS_HOST,
  );
}

/** The settings-assistant chat's image (markdown + recommendation) allowlist. */
export function isSettingsAssistantImageUrl(url: string): boolean {
  return isHttpsUrlWithHost(url, (host) => {
    if (host === SETTINGS_ASSISTANT_DOCS_HOST) return true;
    if (host.endsWith(SETTINGS_ASSISTANT_GITBOOK_ASSET_HOST_SUFFIX)) {
      const prefix = host.slice(
        0,
        host.length - SETTINGS_ASSISTANT_GITBOOK_ASSET_HOST_SUFFIX.length,
      );
      return /^\d+$/.test(prefix);
    }
    if (host === SETTINGS_ASSISTANT_SCREENSHOT_BUCKET_HOST) {
      try {
        return new URL(url).pathname.startsWith(
          SETTINGS_ASSISTANT_SCREENSHOT_PATH_PREFIX,
        );
      } catch {
        return false;
      }
    }
    return false;
  });
}
