// Localised boolean connectors for the dashboard quick-search (DOCB-13123).
//
// Customers search in their own language: a German user types `UND`/`ODER`,
// a French user `ET`/`OU`. The data model stays canonical `AND`/`OR`
// everywhere — localised words exist only at the edges:
//   - input  : recognised when parsing what the user typed
//   - display : rendered in the user's active UI locale
//   - wire    : translated back to canonical before the backend sees them
//
// Input accepts EVERY language below regardless of the active UI locale;
// only the displayed suggestions follow the active locale.
//
// Single-letter or English-colliding connectors (Spanish Y/O, Italian E/O,
// Dutch OF/EN) are intentionally excluded — they collide with field values
// and ordinary English words ("terms of service"). Add a locale here once
// its words are proven unambiguous.

import type { LogicalConnector } from './searchQueryParser';

const CONNECTOR_WORDS_BY_LOCALE: Record<
  string,
  Record<LogicalConnector, string>
> = {
  en: { AND: 'AND', OR: 'OR' },
  de: { AND: 'UND', OR: 'ODER' },
  fr: { AND: 'ET', OR: 'OU' },
};

const FALLBACK_LOCALE = 'en';

function baseLocale(locale: string | undefined | null): string {
  return (locale ?? '').toLowerCase().split('-')[0];
}

export function localeConnectorLabel(
  kind: LogicalConnector,
  locale: string | undefined | null,
): string {
  const words = CONNECTOR_WORDS_BY_LOCALE[baseLocale(locale)];
  return (words ?? CONNECTOR_WORDS_BY_LOCALE[FALLBACK_LOCALE])[kind];
}

const WORD_TO_CANONICAL: Map<string, LogicalConnector> = (() => {
  const map = new Map<string, LogicalConnector>();
  for (const words of Object.values(CONNECTOR_WORDS_BY_LOCALE)) {
    (Object.entries(words) as [LogicalConnector, string][]).forEach(
      ([canonical, word]) => map.set(word.toLowerCase(), canonical),
    );
  }
  return map;
})();

export function canonicalConnectorWord(
  token: string,
): LogicalConnector | undefined {
  return WORD_TO_CANONICAL.get(token.trim().toLowerCase());
}

// Localised words only (canonical AND/OR already match what the backend
// wants, so they need no rewrite). A standalone-token regex keeps the
// translation off substrings: `etwas` and `fundament` survive, ` UND `
// does not.
const LOCALISED_WORDS = [...WORD_TO_CANONICAL.keys()].filter(
  (word) => word !== 'and' && word !== 'or',
);

const TRANSLATE_RE = new RegExp(
  `(^|\\s)(${LOCALISED_WORDS.join('|')})(?=\\s|$)`,
  'gi',
);

export function translateConnectorsForBackend(input: string): string {
  if (!input?.trim()) return input;
  return input.replace(
    TRANSLATE_RE,
    (_match, lead: string, word: string) =>
      lead + (canonicalConnectorWord(word) ?? word),
  );
}

// True when the typed text is a prefix of ANY accepted word for the
// given canonical connector — so typing `u`/`und` (de) or `e`/`et` (fr)
// surfaces the AND suggestion just like `a`/`and` does. Empty query
// matches everything. Drives the autocomplete connector picks.
export function connectorMatchesQuery(
  kind: LogicalConnector,
  query: string,
): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  for (const [word, canonical] of WORD_TO_CANONICAL) {
    if (canonical === kind && word.startsWith(q)) return true;
  }
  return false;
}

// Every accepted connector word across all locales, longest-first so
// `oder` wins over `or` when both could match the same leading run — the
// `\s+` anchor already disambiguates, but ordering keeps the regex
// unambiguous regardless of engine backtracking. Exported so callers can
// build their own connector-aware matchers (e.g. the autocomplete
// caret-boundary walker).
export const CONNECTOR_WORDS = [...WORD_TO_CANONICAL.keys()].sort(
  (a, b) => b.length - a.length,
);

const LEADING_CONNECTOR_RE = new RegExp(
  `^\\s*(${CONNECTOR_WORDS.join('|')})\\s+(.*)$`,
  'i',
);

// Pull a leading connector word (any locale) off the front of a typed
// segment, returning the canonical connector and the remaining text.
// The trailing `\s+` means `und=x` (a field literally named und) and
// `understanding` are NOT treated as connectors.
export function matchLeadingConnector(
  text: string,
): { connector: LogicalConnector; rest: string } | null {
  const match = LEADING_CONNECTOR_RE.exec(text);
  if (!match) return null;
  const connector = canonicalConnectorWord(match[1]);
  return connector ? { connector, rest: match[2] } : null;
}

// All accepted words that fold to the given canonical connector.
export function connectorWordsFor(kind: LogicalConnector): string[] {
  return CONNECTOR_WORDS.filter(
    (word) => canonicalConnectorWord(word) === kind,
  );
}

// Chip-editor input-rule matcher: a connector word sitting at a word
// boundary, immediately followed by the space the user just typed. The
// leading `\b` is what keeps short words (et/ou/und) from firing inside a
// value the user is typing — `budget ` / `for ` must NOT become a
// connector, only a standalone ` ET `/` OU ` does (DOCB-13123).
export function connectorInputRuleRegex(kind: LogicalConnector): RegExp {
  return new RegExp(`\\b(${connectorWordsFor(kind).join('|')})\\s$`, 'i');
}
