/**
 * Cache Recovery Utility — shared primitives for the cache-recovery paths.
 */

import { useLogger } from 'src/utils/logger';

const logger = useLogger('CacheRecovery');

/**
 * Delete all Cache API entries without touching localStorage/sessionStorage/IndexedDB.
 * Used by logout, which keeps its own storage whitelist.
 */
export async function clearServiceWorkerCaches(): Promise<void> {
  if (!('caches' in window)) {
    return;
  }

  try {
    const cacheNames = await caches.keys();
    await Promise.all(cacheNames.map((cacheName) => caches.delete(cacheName)));
    logger.debug(`Cleared ${cacheNames.length} service worker caches`);
  } catch (error) {
    logger.error('Error clearing service worker caches:', error);
  }
}

/**
 * Compare two semantic versions
 * @returns -1 if v1 < v2, 0 if v1 === v2, 1 if v1 > v2
 */
export function compareVersions(v1: string, v2: string): number {
  const parts1 = v1.split('.').map((part) => parseInt(part, 10));
  const parts2 = v2.split('.').map((part) => parseInt(part, 10));

  for (let i = 0; i < Math.max(parts1.length, parts2.length); i++) {
    const part1 = parts1[i] || 0;
    const part2 = parts2[i] || 0;

    if (part1 < part2) return -1;
    if (part1 > part2) return 1;
  }

  return 0;
}
