import { computed, ref, type ComputedRef } from 'vue';
import { LocalStorage } from 'quasar';
import { isUserAdmin } from 'src/utils/UserDetails';
import { getOrgId } from 'src/utils/organization/org_id_helper';

/**
 * A reactive signal for "who is the user, and in which org", for UI that must
 * disappear when a role or an org changes mid-session.
 *
 * The identity itself lives in LocalStorage (`user_details`) and in the active
 * org id — neither of which Vue can observe. A `computed(() => isUserAdmin())`
 * therefore has NO dependency at all: Vue caches the first answer forever and
 * keeps rendering an admin-only surface after the role was revoked.
 *
 * So the identity gets an explicit version counter. Anything that rewrites the
 * persisted identity bumps it (see `user_details.store.ts::getProfile`, the one
 * post-login writer), and every derived computed reads the counter first, which
 * makes the re-read happen.
 *
 * The counter is per tab, so it is only half the story: another tab writing
 * `user_details` (a profile refresh on /settings, an org switch) changes the
 * SHARED record without touching this tab's counter. `handleUserIdentityStorageEvent`
 * closes that gap by listening for the cross-tab `storage` event.
 *
 * This is a render-freshness mechanism, not an authorisation boundary. Requests
 * are gated by uncached call-time checks, and the server enforces the rest.
 */
const USER_DETAILS_KEY = 'user_details';

/**
 * Role claims that belong to a specific session. Carrying them across a new
 * login would let a previous session's admin rights decide what the new one
 * renders, so they are dropped and re-fetched from the profile.
 */
const ROLE_CLAIM_KEYS = [
  'is_admin',
  'is_organisation_admin',
  'is_system_user',
  'organisations',
  'user',
] as const;
const identityVersion = ref(0);

/** Call after the persisted user record or the active org changes. */
export function notifyUserIdentityChanged(): void {
  identityVersion.value += 1;
}

/** Current version — read it to make a computed depend on the identity. */
export function useUserIdentityVersion() {
  return identityVersion;
}

/** Reactive "is the current user an organisation admin". */
export function useIsOrgAdmin(): ComputedRef<boolean> {
  return computed(() => {
    // Establishes the dependency; the value itself is irrelevant.
    void identityVersion.value;
    return isUserAdmin();
  });
}

/** Reactive active organisation id. */
export function useActiveOrgId(): ComputedRef<string> {
  return computed(() => {
    void identityVersion.value;
    return getOrgId();
  });
}

/**
 * The single way to persist the user record. Writing `user_details` directly
 * leaves every gate in the app rendering the previous identity until something
 * unrelated happens to re-evaluate.
 */
export function setPersistedUserIdentity(
  details: Record<string, unknown>,
): void {
  LocalStorage.set(USER_DETAILS_KEY, details);
  notifyUserIdentityChanged();
}

/**
 * Same, for a NEW session: role claims from the previous session are dropped
 * rather than merged, so the app is fail-closed until the profile arrives.
 */
export function replacePersistedUserIdentity(
  details: Record<string, unknown>,
): void {
  const clean: Record<string, unknown> = { ...details };
  ROLE_CLAIM_KEYS.forEach((key) => delete clean[key]);
  setPersistedUserIdentity(clean);
}

/**
 * Cross-tab: another tab rewrote the shared user record (profile refresh, org
 * switch). Only that tab's counter moved, so this one has to be told.
 *
 * Deliberately narrow — it only re-reads the identity. A cross-tab USER or ORG
 * change still gets the hard reload that `handleTokenDetailsStorageEvent` does;
 * this covers the case where only the role or profile changed and
 * `token_details` was never rewritten.
 */
export function handleUserIdentityStorageEvent(event: StorageEvent): void {
  if (event.key !== USER_DETAILS_KEY) return;
  notifyUserIdentityChanged();
}

/** Test seam: reset the counter between specs. */
export function resetUserIdentitySignal(): void {
  identityVersion.value = 0;
}
