import AbstractApiService from 'src/services/abstractApiService';
import { api } from 'pages/APIs';
import type { dynamicObj } from 'src/pages/assets';
import { getDocumentType } from 'src/sdk/api/document-type/document-type';
import logger from 'src/utils/logger';

const sdk = getDocumentType();

export default class DocTypeApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  public async getAllDocumentTypeAttributes(
    attributeKeysCsv: string,
  ): Promise<any> {
    return super.get(
      api.get_all_document_type_attributes +
        '?attribute_keys=' +
        attributeKeysCsv,
      {},
    );
  }

  public async getAttributesByDocKey(data: dynamicObj): Promise<any> {
    let querystring = this.encodeQueryData(data);

    const sub_org_id = await this.getSubOrgId();
    if (sub_org_id) {
      querystring += '&sub_org_id=' + sub_org_id;
    }
    return super.get(api.get_document_type_attributes + '?' + querystring, {});
  }

  public async setAttribute(data: any): Promise<any> {
    // Single source of truth for booleans: route through the typed
    // PUT /document_type/set_document_type_attribute_boolean endpoint (real
    // JSON boolean body) whenever attribute_value is a real boolean, instead
    // of the untyped FormData/String(value) path below. Falls back to the
    // untyped endpoint on the specific 400 the backend returns for
    // attribute_key values outside BOOLEAN_DOCUMENT_TYPE_ATTRIBUTES, so
    // not-yet-registered keys keep working.
    if (typeof data.attribute_value === 'boolean') {
      try {
        const response =
          await sdk.setDocumentTypeAttributeBooleanDocumentTypeSetDocumentTypeAttributeBooleanPut(
            {
              doc_type_key: data.doc_type_key,
              sub_doc_type_key: data.sub_doc_type_key ?? null,
              attribute_key: data.attribute_key,
              attribute_value: data.attribute_value,
              sub_org_id: data.sub_org_id ?? null,
            },
          );
        return { success: true, data: response };
      } catch (boolError: unknown) {
        const errResponse = (
          boolError as { response?: { status?: number; data?: { error_code?: string } } }
        )?.response;
        if (
          errResponse?.status === 400 &&
          errResponse?.data?.error_code === 'NOT_A_BOOLEAN_DOCUMENT_TYPE_ATTRIBUTE'
        ) {
          logger.warn(
            `[DocTypeApiService] attribute_key=${data.attribute_key} not in backend BOOLEAN_DOCUMENT_TYPE_ATTRIBUTES, falling back to untyped endpoint`,
          );
          // fall through to the untyped FormData path below
        } else {
          throw boolError;
        }
      }
    }

    const formData = new FormData();
    for (const [key, value] of Object.entries(data)) {
      formData.append(key, String(value));
    }
    return super.post(api.set_document_type_attribute, formData);
  }

  public async deleteDocumentTypeAttribute(id: string): Promise<any> {
    const formData = new FormData();
    formData.append('id', id);
    return super.delete(api.delete_document_type_attribute, formData);
  }
}
