<template>
  <q-dialog v-model="showOverlay" persistent maximized transition-show="fade" transition-hide="fade">
    <div class="cache-refresh-overlay">
      <q-card class="refresh-card">
        <q-card-section class="text-center">
          <div class="text-h5">Updating DocBits</div>
          <div v-if="showVersionTransition" class="text-caption text-grey-6 q-mt-xs">
            v{{ fromVersion }} &rarr; v{{ toVersion }}
          </div>
        </q-card-section>

        <q-card-section class="progress-section">
          <div class="circular-progress-wrapper">
            <q-circular-progress
              :value="progress"
              size="180px"
              :thickness="0.15"
              :color="progressColor"
              track-color="grey-3"
              class="circular-progress"
              :animation-speed="300"
            >
              <div class="progress-inner">
                <q-icon :name="stepIcon" :size="progressComplete ? '48px' : '36px'" :color="progressColor" class="step-icon" />
                <div class="progress-percentage" :class="{ complete: progressComplete }">
                  {{ progress }}%
                </div>
              </div>
            </q-circular-progress>
          </div>
        </q-card-section>

        <q-card-section class="text-center step-section">
          <span class="step-message">{{ message }}</span>
        </q-card-section>
      </q-card>
    </div>
  </q-dialog>

  <!--
    DOCB-14301 loop-breaker UI. When automated recovery has been exhausted,
    the spinner is replaced by this actionable, DISMISSIBLE message. Never
    `persistent` — the whole bug was users trapped behind an overlay they
    could not close.
  -->
  <q-dialog v-model="showManualRecovery" data-testid="cache-manual-recovery">
    <q-card class="manual-recovery-card">
      <q-card-section class="row items-center no-wrap">
        <q-icon name="warning_amber" color="warning" size="28px" class="q-mr-sm" />
        <div class="text-subtitle1 text-weight-medium">Could not finish updating</div>
      </q-card-section>

      <q-card-section class="q-pt-none">
        <div class="manual-recovery-text">
          DocBits tried to reload automatically but some files are still being served
          from a stale cache. Please reload once with your cache bypassed:
        </div>
        <ul class="manual-recovery-steps">
          <li><strong>Windows / Linux:</strong> Ctrl + Shift + R</li>
          <li><strong>macOS:</strong> Cmd + Shift + R</li>
        </ul>
        <div class="manual-recovery-version">Version {{ fromVersion || 'unknown' }}</div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn flat label="Dismiss" color="grey-7" @click="onDismissManualRecovery" />
        <q-btn unelevated label="Reload now" color="primary" @click="onForceReload" />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useCacheRefreshProgress } from 'src/utils/cacheRefreshProgress';

export default defineComponent({
  name: 'CacheRefreshOverlay',

  setup() {
    // Composable-backed reactive state — the only thing that needs setup().
    const {
      isActive,
      progress,
      message,
      currentStep,
      fromVersion,
      toVersion,
      manualRecoveryRequired,
      dismissManualRecovery,
    } = useCacheRefreshProgress();

    return {
      isActive,
      progress,
      message,
      currentStep,
      fromVersion,
      toVersion,
      manualRecoveryRequired,
      dismissManualRecovery,
    };
  },

  data() {
    return {
      // Local show state to control the dialogs
      showOverlay: false,
      manualRecoveryDismissed: false,
    };
  },

  computed: {
    /**
     * DOCB-14301 display guard (defence in depth — cacheRefreshProgress.start()
     * already refuses to activate for from === to). An "update" caption that
     * shows the same version on both sides is never correct, so we simply do
     * not render it.
     */
    showVersionTransition(): boolean {
      return Boolean(
        this.fromVersion && this.toVersion && this.fromVersion !== this.toVersion,
      );
    },

    showManualRecovery: {
      get(): boolean {
        return this.manualRecoveryRequired && !this.manualRecoveryDismissed;
      },
      set(value: boolean) {
        if (!value) this.manualRecoveryDismissed = true;
      },
    },

    progressComplete(): boolean {
      return this.progress === 100;
    },

    progressColor(): string {
      if (this.progress === 100) return 'positive';
      return 'primary';
    },

    /** Step icon based on current step */
    stepIcon(): string {
      const step = this.currentStep;
      if (step === 6) return 'check_circle'; // Reload step - complete
      if (step >= 5) return 'rocket_launch'; // Prepare step
      if (step >= 4) return 'cleaning_services'; // Unregister SW
      if (step >= 3) return 'delete_sweep'; // Clear caches
      if (step >= 2) return 'storage'; // Clear localStorage
      return 'update'; // Start
    },
  },

  watch: {
    isActive: {
      immediate: true,
      handler(active: boolean) {
        this.showOverlay = active;
      },
    },

    manualRecoveryRequired(required: boolean) {
      // A freshly raised banner must be visible even if a previous one was
      // dismissed earlier in this session.
      if (required) this.manualRecoveryDismissed = false;
    },
  },

  methods: {
    onDismissManualRecovery(): void {
      this.manualRecoveryDismissed = true;
      this.dismissManualRecovery();
    },

    /**
     * Last-resort user-initiated reload. Adds a fresh cache-busting marker so
     * neither the HTTP cache nor the Workbox precache can serve the stale
     * document again.
     */
    onForceReload(): void {
      this.manualRecoveryDismissed = true;
      this.dismissManualRecovery();
      try {
        const url = new URL(window.location.href);
        url.searchParams.set('_refresh', String(Date.now()));
        window.location.replace(url.toString());
      } catch {
        window.location.reload();
      }
    },
  },
});
</script>

