import { date } from 'quasar';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import { dateFormates, date_pattern_setting } from 'src/constants';
import { dateInput } from 'src/formBuilder/form_elements/formatter/TextInput/index';

const TOKENS = {
  '#': { pattern: '[\\d]' },
} as dynamicObj;

const KEYS = Object.keys(TOKENS);
KEYS.forEach((key) => {
  TOKENS[key].regex = new RegExp(TOKENS[key].pattern);
});

// A calendar date, either bare ("2026-08-20") or written as midnight UTC.
// The backend keeps some calendar dates in timestamptz columns (e.g.
// purchase_order_line.promised_delivery_date) and sends them as
// "2026-08-20T00:00:00+00:00". Postgres text uses "+00"; naive values have
// no offset. Group 1 captures the calendar date. (DRFS-808)
const CALENDAR_DATE_VALUE =
  /^(\d{4}-\d{2}-\d{2})(?:[T ]00:00:00(?:\.0+)?(?:Z|[+-]00(?::?00)?)?)?$/;

/**
 * Returns the YYYY-MM-DD calendar date carried by a date-only value, or
 * null when the value holds a real time of day. Date-only columns render
 * this date as it is: converting midnight UTC to local time puts it on the
 * previous day west of UTC.
 */
export function calendarDateOf(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }
  const match = CALENDAR_DATE_VALUE.exec(value.trim());
  return match ? match[1] : null;
}

// True when a Quasar/dayjs display pattern prints a time of day (hours,
// minutes or seconds). Text inside [brackets] is literal and is ignored.
function patternShowsTime(pattern: string): boolean {
  return /[Hhms]/.test(pattern.replace(/\[[^\]]*\]/g, ''));
}

export default {
  methods: {
    isDateMatchMask(date: string, mask: string) {
      if (date === void 0 || date === null || date === '') {
        return false;
      }

      let is_valid = true;
      let valIndex = 0;

      for (let maskIndex = 0; maskIndex < mask.length; maskIndex++) {
        const maskDef = mask[maskIndex];
        const valChar = date[valIndex];

        if (typeof maskDef === 'string' && valChar === maskDef) {
          valIndex++;
          continue;
        }

        const c = TOKENS[maskDef];
        if (!c || !c.hasOwnProperty('regex') || !c.regex.test(valChar)) {
          is_valid = false;
          break;
        }
        valIndex++;
      }

      return is_valid;
    },

    formatDate(date: any) {
      // The output is a calendar date. A calendar-date input keeps its day
      // in every timezone (DRFS-808).
      const calendarDate = calendarDateOf(date);
      if (calendarDate) {
        return calendarDate;
      }
      const d = new Date(date);
      let month = '' + (d.getMonth() + 1);
      let day = '' + d.getDate();
      const year = d.getFullYear();

      if (month.length < 2) month = '0' + month;
      if (day.length < 2) day = '0' + day;

      return [year, month, day].join('-');
    },

    formatDateWithPattern(strDate: string, dateFormat: string) {
      if (!strDate) {
        return '';
      }

      if (!dateFormat) {
        dateFormat = dateFormates.date_only;
      }

      // A date-only pattern shows a calendar date. If the value is a
      // calendar date too (bare, or midnight UTC), print that date as it is.
      // Quasar would otherwise parse it as UTC midnight and render the
      // previous local day west of UTC (DRFS-808). Anchoring to local
      // midnight keeps the day in every timezone.
      const calendarDate = patternShowsTime(dateFormat)
        ? null
        : calendarDateOf(strDate);
      if (calendarDate) {
        return date.formatDate(`${calendarDate} 00:00:00`, dateFormat);
      }

      return date.formatDate(strDate, dateFormat);
    },

    getDatePattern() {
      return dateInput.getFormat(this.getDocDateFormat());
    },

    compareDates(strDate1: string, strDate2: string) {
      if (!strDate1 || !strDate2) {
        return false;
      }

      return new Date(strDate1) >= new Date(strDate2);
    },

    dateDifferenceInDays(strDate1: string, strDate2: string) {
      if (!strDate1 || !strDate2) {
        return 0;
      }

      const differenceInTime =
        new Date(strDate1).getTime() - new Date(strDate2).getTime();

      return Math.round(differenceInTime / (1000 * 3600 * 24));
    },

    dateDifferenceInMiliSec(strDate1: string, strDate2: string) {
      if (!strDate1 || !strDate2) {
        return 0;
      }

      return new Date(strDate1).getTime() - new Date(strDate2).getTime();
    },

    isDate(dateString: string) {
      return !isNaN(Date.parse(dateString));
    },

    getDocDateFormat() {
      const settings_store = useSettingStore();
      const pref = settings_store.user_settings[date_pattern_setting];
      return pref ? String(pref) : dateFormates.date_only;
    },

    getJsDateFormate() {
      return dateInput.getFormat(this.getDocDateFormat());
    },

    formatDateAccordingToPreference(
      dateString: string,
      showDateOnly = false,
      defaultValue = '-',
    ) {
      if (!dateString) {
        return defaultValue;
      } else if (!this.isDate(dateString)) {
        return dateString;
      }

      const datePattern = dateInput.getFormat(this.getDocDateFormat());

      // A bare YYYY-MM-DD has no time of day, so it always gets the
      // date-only mask. No fabricated 00:00:00 reaches the UI.
      // formatDateWithPattern keeps a calendar date's day in every
      // timezone when the mask is date-only (DRFS-808). A midnight-UTC
      // timestamp in a datetime column still renders as an instant.
      const isBareDate =
        typeof dateString === 'string' &&
        calendarDateOf(dateString) === dateString.trim();
      const dateFormat =
        showDateOnly || isBareDate ? datePattern : `${datePattern} HH:mm:ss`;
      return this.formatDateWithPattern(dateString, dateFormat);
    },

    // Parse a backend timestamp into a Date on the correct instant.
    // A naive timestamp (no trailing Z / ±HH:MM offset) is treated as UTC —
    // backend stores UTC without an offset — so appending 'Z' anchors it to
    // the right instant; an offset-bearing input is parsed as-is. The returned
    // Date's LOCAL getters then yield the viewer's wall-clock time, so every
    // viewer sees the same instant in their own zone (never NaN / "Invalid").
    toUtcAwareDate(strDate: string): Date | null {
      if (!strDate) {
        return null;
      }
      let dateObj: Date;
      try {
        if (!/Z$|[+-]\d{2}:?\d{2}$/.test(strDate)) {
          dateObj = new Date(strDate + 'Z'); // force UTC on naive timestamps
        } else {
          dateObj = new Date(strDate);
        }
      } catch {
        return null;
      }
      return isNaN(dateObj.getTime()) ? null : dateObj;
    },

    formatDateTimeZone(strDate: string, isDateOnly = false) {
      if (!strDate) {
        return '-';
      }

      // A date-only column shows the calendar date as it was sent, with no
      // conversion. See calendarDateOf / DRFS-808.
      const calendarDate = isDateOnly ? calendarDateOf(strDate) : null;
      if (calendarDate) {
        const datePattern = dateInput.getFormat(this.getDocDateFormat());
        if (!datePattern || datePattern == 'undefined') {
          return calendarDate;
        }
        return this.formatDateWithPattern(calendarDate, datePattern);
      }

      // Parse UTC-aware (naive -> UTC, offset-bearing -> as-is).
      const dateObj = this.toUtcAwareDate(strDate);
      if (!dateObj) {
        return strDate; // fallback if invalid date
      }

      // Format into local timezone
      const year = dateObj.getFullYear();
      const month = (dateObj.getMonth() + 1).toString().padStart(2, '0');
      const day = dateObj.getDate().toString().padStart(2, '0');
      const hours = dateObj.getHours().toString().padStart(2, '0');
      const minutes = dateObj.getMinutes().toString().padStart(2, '0');
      const seconds = dateObj.getSeconds().toString().padStart(2, '0');

      let formatted;
      let dateFormat;

      if (isDateOnly) {
        formatted = `${year}-${month}-${day}`;
        dateFormat = dateInput.getFormat(this.getDocDateFormat());
      } else {
        formatted = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
        dateFormat = dateInput.getFormat(this.getDocDateFormat()) + ' HH:mm:ss';
      }

      if (!dateFormat || dateFormat == 'undefined') {
        return formatted;
      }
      return this.formatDateWithPattern(formatted, dateFormat);
    },

    formatSecondsToHoursMinutes(value: number) {
      const totalSeconds = Math.floor(value);
      const hours = Math.floor(totalSeconds / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      const parts: string[] = [];
      if (hours > 0) parts.push(`${hours}h`);
      if (minutes > 0) parts.push(`${minutes}m`);
      parts.push(`${seconds}s`);

      return parts.join(' ');
    },

    /**
     * Format duration in seconds to human-readable format with smart unit selection.
     *
     * Rules:
     * - < 60 seconds: show seconds only (e.g., "45s")
     * - >= 60 seconds and < 1 hour: show minutes and seconds (e.g., "5m 30s")
     * - >= 1 hour and < 1 day: show hours and minutes only, NO seconds (e.g., "2h 15m")
     * - >= 1 day: show days and hours only, NO minutes (e.g., "3d 5h")
     *
     * @param value - Duration in seconds
     * @returns Formatted duration string
     */
    formatDuration(value: number): string {
      if (typeof value !== 'number' || isNaN(value) || value < 0) {
        return '<1s';
      }

      const totalSeconds = Math.floor(value);

      // Value > 0 but rounds to 0 seconds: show <1s
      if (totalSeconds === 0) {
        return '<1s';
      }

      const days = Math.floor(totalSeconds / 86400);
      const hours = Math.floor((totalSeconds % 86400) / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      // >= 1 day: show days and hours only
      if (days > 0) {
        if (hours > 0) {
          return `${days}d ${hours}h`;
        }
        return `${days}d`;
      }

      // >= 1 hour: show hours and minutes only (NO seconds)
      if (hours > 0) {
        if (minutes > 0) {
          return `${hours}h ${minutes}m`;
        }
        return `${hours}h`;
      }

      // >= 60 seconds: show minutes and seconds
      if (minutes > 0) {
        if (seconds > 0) {
          return `${minutes}m ${seconds}s`;
        }
        return `${minutes}m`;
      }

      // < 60 seconds: show seconds only
      return `${seconds}s`;
    },

    // Converts any date string to universal format (YYYY-MM-DD)
    formatDateToUniversal(dateStr: string) {
      if (!dateStr) {
        return '-';
      }

      // YYYY-MM-DD or YYYY/MM/DD
      if (dateStr.match(/^\d{4}[/-]\d{2}[/-]\d{2}$/)) {
        return dateStr.replace(/\//g, '-');
      }

      // Get user's date format preference to correctly parse ambiguous formats
      const userPattern = this.getDatePattern();

      // MM/DD/YYYY (US format)
      if (
        dateStr.match(/^\d{2}\/\d{2}\/\d{4}$/) &&
        userPattern === 'MM/DD/YYYY'
      ) {
        const dateParts = dateStr.split('/');
        return `${dateParts[2]}-${dateParts[0]}-${dateParts[1]}`;
      }

      // DD/MM/YYYY (European format)
      if (dateStr.match(/^\d{2}\/\d{2}\/\d{4}$/)) {
        const dateParts = dateStr.split('/');
        return `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;
      }

      // DD.MM.YYYY
      if (dateStr.match(/^\d{2}\.\d{2}\.\d{4}$/)) {
        const dateParts = dateStr.split('.');
        return `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;
      }

      if (!this.isDate(dateStr)) {
        return dateStr;
      }

      return this.formatDate(dateStr);
    },
  },
};
