// Document transformation rules (per doc-type).
//
// A transformation rule reads a value, runs it through an ordered pipeline of
// actions, and writes the result back — or, for `document` scope, stamps a
// document attribute (routing) instead of touching a field.
//
// GET /transformation-rules?doc_type=INVOICE

import AbstractApiService from 'src/services/abstractApiService';
import { api } from 'pages/APIs';

/** Where the rule writes its result.
 *  header   — one value per document (supplier, tax id, …)
 *  column   — a value in every line-item row
 *  table    — whole line-item rows (add / clear), not the values inside them
 *  document — a document attribute (routing, e.g. sub_org_id) */
export type TransformationRuleScope = 'header' | 'column' | 'table' | 'document';

/** Origin of a rule row, as resolved by the backend overlay. */
export type TransformationRuleSourceBadge = 'system_default' | 'customized' | 'custom';

/** One step of the pipeline. `type` selects the action; `params` carries that
 *  action's own options (shape per action — see ACTION_CATALOGUE). */
export interface TransformationAction {
  type: string;
  params?: Record<string, unknown>;
  [key: string]: unknown;
}

/** A single condition node. Kept loose because applies_when is a recursive
 *  all/any tree — the same encoding the custom-validation rules use. */
export interface TransformationRuleCondition {
  op?: string;
  field?: string;
  value?: unknown;
  case_insensitive?: boolean;
  not?: TransformationRuleCondition;
  [key: string]: unknown;
}

export interface TransformationRuleAppliesWhen {
  all?: TransformationRuleCondition[];
  any?: TransformationRuleCondition[];
  [key: string]: unknown;
}

export interface TransformationRule {
  id: string;
  doc_type: string;
  scope: TransformationRuleScope;
  rule_key: string;
  display_name: string;
  description: string | null;
  /** The field/column/attribute the result is written to. */
  target_field: string;
  /** Namespaced field the pipeline READS from (e.g. `header.article_number`).
   *  Null means "read the target itself" (in-place transform). */
  source: string | null;
  /** The document table a column- or table-scoped rule targets (null otherwise). */
  table_name: string | null;
  applies_when: TransformationRuleAppliesWhen | null;
  actions: TransformationAction[];
  priority: number;
  is_active: boolean;
  /** Apply at most once per document. Rules otherwise re-run on every save; a
   *  pass where applies_when does NOT match never counts as applied, so the
   *  rule stays eligible for a later save. */
  run_once: boolean;
  /** Also apply in the extra pass that runs after master data lookup and before
   *  PO matching, so the rule can read supplier master values and PO matching
   *  sees the result. Only rules with this set take part in that pass; a rule
   *  that has it still runs at its usual passes too. */
  run_after_lookup: boolean;
  log_execution: boolean;
  source_badge: TransformationRuleSourceBadge;
  /** CORE-6103 — how the rule was created: 'assistant' (settings-assistant
   *  chat) or 'mcp' (MCP client); 'ui'/'api'/null otherwise. Older API
   *  versions omit it. */
  created_via?: string | null;
  // Audit trail. `*_by` carry the actor id (null for system-seeded rules);
  // `*_by_name` carry the resolved display name for the list.
  created_by: number | null;
  created_by_name: string | null;
  created_on: string | null;
  last_modified_by: string | null;
  last_modified_by_name: string | null;
  last_modified_on: string | null;
}

/** Body for POST /transformation-rules (create). */
export interface CreateTransformationRulePayload {
  doc_type: string;
  scope: TransformationRuleScope;
  /** Omitted → the backend derives it from display_name. */
  rule_key?: string | null;
  display_name: string;
  description?: string | null;
  target_field: string;
  source?: string | null;
  table_name?: string | null;
  /** Omitted entirely when the rule has no conditions — an empty match
   *  ({ all: [] }) is not sent; its absence means "applies unconditionally". */
  applies_when?: TransformationRuleAppliesWhen | null;
  /** At least one action is required by the API (minItems: 1). */
  actions: TransformationAction[];
  priority?: number;
  is_active?: boolean;
  /** Apply at most once per document (see TransformationRule.run_once). */
  run_once?: boolean;
  /** Take part in the post-lookup pass (see TransformationRule.run_after_lookup). */
  run_after_lookup?: boolean;
  log_execution?: boolean;
}

/** Body for PUT /transformation-rules/{id} (update).
 *  doc_type / scope / rule_key are immutable and omitted. */
export type UpdateTransformationRulePayload = Omit<
  CreateTransformationRulePayload,
  'doc_type' | 'scope' | 'rule_key'
>;

/** Body for POST /transformation-rules/{id}/clone.
 *  The backend copies the source rule's whole definition; only the new row's
 *  identity is supplied. */
export interface CloneTransformationRulePayload {
  rule_key: string;
  display_name: string;
}

export default class TransformationRulesApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  // The org is passed via the x-org-id header on every request, so these
  // endpoints must NOT get org_id injected into the body or query string —
  // hence the *WithoutOrgId variants throughout.

  /** List the transformation rules configured for a doc type: system defaults
   *  overlaid with the org's own rows, each tagged with its source badge. */
  public async list(docType: string): Promise<TransformationRule[]> {
    const url = `${api.transformation_rules}?doc_type=${encodeURIComponent(docType)}`;
    return super.getWithoutOrgId(url);
  }

  /** Fetch a single rule by id. GET /transformation-rules/{id} */
  public async getById(ruleId: string): Promise<TransformationRule> {
    const url = `${api.transformation_rules}/${encodeURIComponent(ruleId)}`;
    return super.getWithoutOrgId(url);
  }

  /** Create a new rule. POST /transformation-rules */
  public async create(
    payload: CreateTransformationRulePayload,
  ): Promise<TransformationRule> {
    return super.postWithoutOrgId(api.transformation_rules, { ...payload });
  }

  /** Update a rule. PUT /transformation-rules/{id}
   *  Updating a system default creates (or reuses) the org's override row. */
  public async update(
    ruleId: string,
    payload: UpdateTransformationRulePayload,
  ): Promise<TransformationRule> {
    const url = `${api.transformation_rules}/${encodeURIComponent(ruleId)}`;
    return super.put(url, { ...payload }, { skipOrgId: true });
  }

  /** Enable/disable a rule. Toggling a system default creates the org override
   *  row (same rule_key) with the requested state.
   *  PATCH /transformation-rules/{id}/toggle  { is_active } */
  public async setActive(
    ruleId: string,
    isActive: boolean,
  ): Promise<TransformationRule> {
    const url = `${api.transformation_rules}/${encodeURIComponent(ruleId)}/toggle`;
    return super.patch(url, { is_active: isActive }, { skipOrgId: true });
  }

  /** Create the org's editable copy of a system default, pre-filled with the
   *  default's values. Idempotent — an existing override is returned unchanged.
   *  POST /transformation-rules/{id}/customize */
  public async customize(ruleId: string): Promise<TransformationRule> {
    const url = `${api.transformation_rules}/${encodeURIComponent(ruleId)}/customize`;
    return super.postWithoutOrgId(url, {});
  }

  /** Copy an existing rule (including a system default) into a new org rule
   *  under the given key/name. The backend duplicates the full definition, so
   *  no body beyond the new identity is needed.
   *  POST /transformation-rules/{id}/clone  { rule_key, display_name } */
  public async clone(
    ruleId: string,
    payload: CloneTransformationRulePayload,
  ): Promise<TransformationRule> {
    const url = `${api.transformation_rules}/${encodeURIComponent(ruleId)}/clone`;
    return super.postWithoutOrgId(url, { ...payload });
  }

  /** Soft-delete an org rule. For an override this resets the org back to the
   *  system default. DELETE /transformation-rules/{id} */
  public async deleteTransformationRule(ruleId: string): Promise<void> {
    const url = `${api.transformation_rules}/${encodeURIComponent(ruleId)}`;
    return super.deleteWithoutOrgId<void>(url);
  }

}
